-- Aprenda se Divertindo · 91 · Baralho de cartões · trilha Policial · mais 500 cartões (total de 1.500)
-- Rode depois do 90-simulado-saude-1.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Assuntos novos, conferidos contra os 3.000 cartões já existentes para não repetir: crimes contra a honra, lesão corporal,
-- feminicídio (art. 121-A), dosimetria, penas e regimes, crimes funcionais, provas e testemunhas, prisões e cautelares,
-- júri, recursos, Juizados, Lei Henry Borel, LEP (percentuais de progressão), lavagem, terrorismo, crimes ambientais,
-- balística e tanatologia, sistema interamericano, Lei 14.532/2023 (racismo), Estatuto da Pessoa com Deficiência,
-- IA, sustentabilidade, informática, raciocínio lógico e Português, sempre com a base legal.
-- Cartões numerados de 2.000.003.001 a 2.000.003.500. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000003001, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pares", "frente": "Qual a diferença entre calúnia, difamação e injúria?", "verso": "Calúnia: imputar falsamente fato definido como crime. Difamação: imputar fato ofensivo à reputação (não precisa ser crime). Injúria: ofender a dignidade ou o decoro, sem imputar fato.", "explicacao": "CP, arts. 138, 139 e 140."}, {"id": 2000003002, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pergunta", "frente": "Cabe exceção da verdade na injúria?", "verso": "Não. A injúria não imputa fato, então não há o que provar. A exceção da verdade cabe, em regra, na calúnia e, na difamação, só contra funcionário público em razão das funções.", "explicacao": "CP, arts. 138, § 3º, 139, parágrafo único, e 140."}, {"id": 2000003003, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pergunta", "frente": "Até quando a retratação isenta de pena o querelado na calúnia e na difamação?", "verso": "Até antes da sentença, se ele se retratar cabalmente.", "explicacao": "CP, art. 143. Não vale para a injúria."}, {"id": 2000003004, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pergunta", "frente": "Injurar alguém usando elementos de raça, cor, etnia ou procedência nacional é que crime hoje?", "verso": "Injúria racial, tipificada na Lei do Racismo (Lei 7.716/1989, art. 2º-A), com pena de reclusão de 2 a 5 anos.", "explicacao": "Mudança feita pela Lei 14.532/2023: equiparou a injúria racial ao racismo."}, {"id": 2000003005, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "certo_errado", "frente": "Certo ou errado? A calúnia contra os mortos é punível.", "verso": "Certo.", "explicacao": "CP, art. 138, § 2º."}, {"id": 2000003006, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pergunta", "frente": "Quais resultados tornam a lesão corporal grave (art. 129, § 1º)?", "verso": "Incapacidade para as ocupações habituais por mais de 30 dias, perigo de vida, debilidade permanente de membro, sentido ou função e aceleração de parto.", "explicacao": "CP, art. 129, § 1º."}, {"id": 2000003007, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pares", "frente": "Qual a diferença entre aceleração de parto e aborto como resultado da lesão corporal?", "verso": "Aceleração de parto: o bebê nasce vivo antes do tempo, e a lesão é grave. Aborto: há morte do feto, e a lesão é gravíssima.", "explicacao": "CP, art. 129, § 1º, IV, e § 2º, V."}, {"id": 2000003008, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pergunta", "frente": "A lesão corporal leve praticada contra a mulher em violência doméstica depende de representação?", "verso": "Não. A ação penal é pública incondicionada.", "explicacao": "Súmula 542 do STJ e ADI 4.424 do STF."}, {"id": 2000003009, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pergunta", "frente": "Qual a ação penal da lesão corporal leve e da lesão culposa, em regra?", "verso": "Pública condicionada à representação.", "explicacao": "Lei 9.099/1995, art. 88."}, {"id": 2000003010, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pares", "frente": "Qual a diferença entre motivo torpe e motivo fútil?", "verso": "Torpe: motivo vil, repugnante (ex.: matar por herança ou por pagamento). Fútil: motivo insignificante, desproporcional (ex.: matar por uma briga de trânsito banal).", "explicacao": "CP, art. 121, § 2º, I e II."}, {"id": 2000003011, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Em que casos o aborto praticado por médico não é punido pelo Código Penal?", "verso": "Aborto necessário (não há outro meio de salvar a vida da gestante) e aborto em gravidez resultante de estupro, com consentimento da gestante ou do representante legal.", "explicacao": "CP, art. 128. O STF também afastou o crime no caso de feto anencéfalo (ADPF 54)."}, {"id": 2000003012, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Induzir ou instigar alguém a se automutilar é crime?", "verso": "Sim. O art. 122 do CP passou a punir também o induzimento, a instigação ou o auxílio à automutilação.", "explicacao": "Alteração da Lei 13.968/2019."}, {"id": 2000003013, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "certo_errado", "frente": "Certo ou errado? No homicídio culposo, o juiz pode deixar de aplicar a pena se as consequências atingirem o próprio agente de forma tão grave que a sanção se torne desnecessária.", "verso": "Certo. É o perdão judicial.", "explicacao": "CP, art. 121, § 5º."}, {"id": 2000003014, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre roubo próprio e roubo impróprio?", "verso": "Próprio: a violência ou grave ameaça é usada antes ou durante a subtração. Impróprio: logo depois de subtrair, o agente usa violência ou grave ameaça para garantir a impunidade ou a posse da coisa.", "explicacao": "CP, art. 157, caput e § 1º."}, {"id": 2000003015, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Há latrocínio consumado se o homicídio se consumou, mas a subtração não?", "verso": "Sim.", "explicacao": "Súmula 610 do STF."}, {"id": 2000003016, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre roubo e extorsão?", "verso": "No roubo, o agente subtrai a coisa (a colaboração da vítima é dispensável). Na extorsão, a vítima é constrangida a fazer, tolerar ou deixar de fazer algo, e sua colaboração é indispensável para a vantagem.", "explicacao": "CP, arts. 157 e 158."}, {"id": 2000003017, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual crime comete quem sequestra pessoa com o fim de obter vantagem como condição ou preço do resgate?", "verso": "Extorsão mediante sequestro.", "explicacao": "CP, art. 159. É crime hediondo em todas as suas formas."}, {"id": 2000003018, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre furto mediante fraude e estelionato?", "verso": "No furto mediante fraude, a fraude distrai a vítima para o agente subtrair a coisa. No estelionato, a fraude leva a vítima a entregar a coisa voluntariamente.", "explicacao": "CP, arts. 155, § 4º, II, e 171."}, {"id": 2000003019, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Após o Pacote Anticrime, qual é a regra da ação penal no estelionato?", "verso": "Pública condicionada à representação, salvo se a vítima for a Administração Pública, criança ou adolescente, pessoa com deficiência mental, maior de 70 anos ou incapaz.", "explicacao": "CP, art. 171, § 5º, incluído pela Lei 13.964/2019."}, {"id": 2000003020, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é apropriação indébita?", "verso": "Apropriar-se de coisa alheia móvel de que tem a posse ou a detenção.", "explicacao": "CP, art. 168. A posse é anterior e lícita; o dolo de se apropriar surge depois."}, {"id": 2000003021, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "certo_errado", "frente": "Certo ou errado? O crime de dano é praticado por quem destrói, inutiliza ou deteriora coisa alheia.", "verso": "Certo.", "explicacao": "CP, art. 163."}, {"id": 2000003022, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Qual a diferença entre peculato-apropriação e peculato-furto?", "verso": "Peculato-apropriação: o funcionário se apropria de bem que já tem a posse em razão do cargo. Peculato-furto: ele não tem a posse, mas subtrai ou concorre para a subtração, valendo-se da facilidade do cargo.", "explicacao": "CP, art. 312, caput e § 1º."}, {"id": 2000003023, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é o peculato mediante erro de outrem?", "verso": "Apropriar-se de dinheiro ou utilidade que, no exercício do cargo, recebeu por erro de outra pessoa.", "explicacao": "CP, art. 313."}, {"id": 2000003024, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Qual crime pratica o funcionário autorizado que insere dados falsos em sistema da Administração para obter vantagem?", "verso": "Inserção de dados falsos em sistema de informações.", "explicacao": "CP, art. 313-A."}, {"id": 2000003025, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é condescendência criminosa?", "verso": "Deixar o funcionário, por indulgência, de responsabilizar subordinado que cometeu infração no cargo, ou de levar o fato ao conhecimento da autoridade competente.", "explicacao": "CP, art. 320."}, {"id": 2000003026, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Qual crime pratica o funcionário que revela fato de que tem ciência em razão do cargo e que deva permanecer em segredo?", "verso": "Violação de sigilo funcional.", "explicacao": "CP, art. 325."}, {"id": 2000003027, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Qual o aumento de pena quando o autor de crime funcional ocupa cargo em comissão ou função de direção?", "verso": "Aumento de 1/3.", "explicacao": "CP, art. 327, § 2º."}, {"id": 2000003028, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Qual a diferença entre resistência e desobediência?", "verso": "Resistência: opor-se à execução de ato legal com violência ou ameaça ao funcionário. Desobediência: simplesmente não cumprir ordem legal, sem violência ou ameaça.", "explicacao": "CP, arts. 329 e 330."}, {"id": 2000003029, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Qual a diferença entre contrabando e descaminho?", "verso": "Contrabando: importar ou exportar mercadoria proibida. Descaminho: iludir o pagamento de tributo na entrada ou saída de mercadoria permitida.", "explicacao": "CP, arts. 334-A e 334."}, {"id": 2000003030, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Qual a diferença entre denunciação caluniosa e comunicação falsa de crime?", "verso": "Denunciação caluniosa: dar causa a investigação ou processo contra alguém, imputando-lhe crime de que o sabe inocente. Comunicação falsa: provocar a ação da autoridade comunicando crime que sabe não ter ocorrido, sem apontar autor determinado.", "explicacao": "CP, arts. 339 e 340."}, {"id": 2000003031, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "No falso testemunho, o que acontece se o agente se retrata antes da sentença no processo em que ocorreu o ilícito?", "verso": "O fato deixa de ser punível.", "explicacao": "CP, art. 342, § 2º."}, {"id": 2000003032, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "certo_errado", "frente": "Certo ou errado? No favorecimento pessoal, fica isento de pena o ascendente, descendente, cônjuge ou irmão do criminoso que presta o auxílio.", "verso": "Certo.", "explicacao": "CP, art. 348, § 2º."}, {"id": 2000003033, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "pergunta", "frente": "Atribuir-se falsa identidade perante a autoridade policial para ocultar maus antecedentes é crime?", "verso": "Sim. É crime de falsa identidade, e não exercício de autodefesa.", "explicacao": "Súmula 522 do STJ e CP, art. 307."}, {"id": 2000003034, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "pergunta", "frente": "Qual crime comete quem faz uso de documento que sabe ser falso?", "verso": "Uso de documento falso, com a mesma pena da falsificação.", "explicacao": "CP, art. 304."}, {"id": 2000003035, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "O consentimento da vítima menor de 14 anos afasta o estupro de vulnerável?", "verso": "Não. Também é irrelevante sua experiência sexual anterior ou eventual relacionamento com o agente.", "explicacao": "Súmula 593 do STJ e CP, art. 217-A, § 5º."}, {"id": 2000003036, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "Qual crime comete quem reduz alguém a condição análoga à de escravo?", "verso": "O do art. 149 do CP, que abrange trabalhos forçados, jornada exaustiva, condições degradantes ou restrição de locomoção por dívida.", "explicacao": "CP, art. 149."}, {"id": 2000003037, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "O que é violação de domicílio?", "verso": "Entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade de quem de direito, em casa alheia ou em suas dependências.", "explicacao": "CP, art. 150."}, {"id": 2000003038, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a paz pública", "tipo": "pares", "frente": "Qual a diferença entre associação criminosa e associação para o tráfico?", "verso": "Associação criminosa: 3 ou mais pessoas para cometer crimes em geral (CP, art. 288). Associação para o tráfico: 2 ou mais pessoas para praticar tráfico (Lei 11.343/2006, art. 35).", "explicacao": "Os dois crimes se consumam com a associação estável, ainda que nenhum crime-fim seja praticado."}, {"id": 2000003039, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a paz pública", "tipo": "pergunta", "frente": "O que é o crime de constituição de milícia privada?", "verso": "Constituir, organizar, integrar, manter ou custear organização paramilitar, milícia particular, grupo ou esquadrão para praticar crimes do Código Penal.", "explicacao": "CP, art. 288-A."}, {"id": 2000003040, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a paz pública", "tipo": "pares", "frente": "Qual a diferença entre incitação ao crime e apologia de crime?", "verso": "Incitação: estimular publicamente a prática de crime. Apologia: fazer publicamente elogio de fato criminoso ou de seu autor.", "explicacao": "CP, arts. 286 e 287."}, {"id": 2000003041, "trilha": "policial", "materia": "pen", "assunto": "Periclitação da vida", "tipo": "pergunta", "frente": "O que é o crime de rixa?", "verso": "Participar de luta tumultuosa entre três ou mais pessoas, com agressões recíprocas, salvo para separar os contendores.", "explicacao": "CP, art. 137."}, {"id": 2000003042, "trilha": "policial", "materia": "pen", "assunto": "Extinção da punibilidade", "tipo": "pares", "frente": "Qual a diferença entre anistia, graça e indulto?", "verso": "Anistia: lei do Congresso que apaga o fato criminoso. Graça: perdão individual concedido pelo Presidente. Indulto: perdão coletivo concedido pelo Presidente, por decreto.", "explicacao": "CF, arts. 21, XVII, 48, VIII, e 84, XII."}, {"id": 2000003043, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Quando os prazos de prescrição são reduzidos pela metade?", "verso": "Quando o criminoso era menor de 21 anos na data do fato ou maior de 70 anos na data da sentença.", "explicacao": "CP, art. 115."}, {"id": 2000003044, "trilha": "policial", "materia": "pen", "assunto": "Concurso de crimes", "tipo": "pergunta", "frente": "Qual o aumento de pena no crime continuado simples?", "verso": "De 1/6 a 2/3, aplicado à pena de um só dos crimes, se idênticas, ou à mais grave, se diversas.", "explicacao": "CP, art. 71. No continuado específico (crimes dolosos com violência contra vítimas diferentes), o aumento pode chegar ao triplo."}, {"id": 2000003045, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais são as três fases da dosimetria da pena?", "verso": "1ª: pena-base pelas circunstâncias judiciais do art. 59. 2ª: agravantes e atenuantes. 3ª: causas de aumento e de diminuição.", "explicacao": "CP, art. 68 (critério trifásico de Nélson Hungria)."}, {"id": 2000003046, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais são as penas restritivas de direitos do art. 43 do CP?", "verso": "Prestação pecuniária, perda de bens e valores, prestação de serviço à comunidade ou a entidades públicas, interdição temporária de direitos e limitação de fim de semana.", "explicacao": "CP, art. 43."}, {"id": 2000003047, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quando a pena privativa de liberdade pode ser substituída por restritiva de direitos?", "verso": "Pena não superior a 4 anos e crime sem violência ou grave ameaça (ou qualquer pena, se culposo), réu não reincidente em crime doloso e circunstâncias judiciais favoráveis.", "explicacao": "CP, art. 44."}, {"id": 2000003048, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual o regime inicial para condenado não reincidente com pena superior a 4 e até 8 anos?", "verso": "Pode começar no semiaberto.", "explicacao": "CP, art. 33, § 2º, b. Acima de 8 anos, fechado; até 4 anos, aberto (se não reincidente)."}, {"id": 2000003049, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais os limites da pena de multa no Código Penal?", "verso": "De 10 a 360 dias-multa, e cada dia-multa vale de 1/30 do salário mínimo até 5 vezes esse salário.", "explicacao": "CP, art. 49."}, {"id": 2000003050, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual a fração mínima de pena para o livramento condicional do condenado não reincidente em crime doloso e com bons antecedentes?", "verso": "Mais de 1/3 da pena.", "explicacao": "CP, art. 83, I. Reincidente em crime doloso: mais da metade. Hediondos: mais de 2/3, vedado ao reincidente específico."}, {"id": 2000003051, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pares", "frente": "Qual embriaguez exclui a culpabilidade?", "verso": "Só a completa, proveniente de caso fortuito ou força maior. A voluntária ou culposa não exclui. A preordenada (beber para criar coragem) é agravante.", "explicacao": "CP, art. 28, II e § 1º, e art. 61, II, l."}, {"id": 2000003052, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "O que é a semi-imputabilidade?", "verso": "Quando o agente, por perturbação de saúde mental ou desenvolvimento mental incompleto ou retardado, não era inteiramente capaz de entender o caráter ilícito do fato. A pena pode ser reduzida de 1/3 a 2/3.", "explicacao": "CP, art. 26, parágrafo único."}, {"id": 2000003053, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pares", "frente": "Qual a diferença entre coação moral irresistível e obediência hierárquica?", "verso": "Na coação irresistível, só é punido o autor da coação. Na obediência a ordem não manifestamente ilegal de superior hierárquico, só é punido o autor da ordem.", "explicacao": "CP, art. 22. As duas excluem a culpabilidade por inexigibilidade de conduta diversa."}, {"id": 2000003054, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Qual a diferença entre erro de tipo e erro de proibição?", "verso": "Erro de tipo: o agente se engana sobre um elemento do fato (exclui o dolo). Erro de proibição: ele sabe o que faz, mas acha que é permitido (se inevitável, isenta de pena; se evitável, reduz de 1/6 a 1/3).", "explicacao": "CP, arts. 20 e 21."}, {"id": 2000003055, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "pergunta", "frente": "O agente que age em legítima defesa responde pelo excesso?", "verso": "Sim. Responde pelo excesso doloso ou culposo, em qualquer das excludentes de ilicitude.", "explicacao": "CP, art. 23, parágrafo único."}, {"id": 2000003056, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pares", "frente": "Qual a diferença entre crime material, formal e de mera conduta?", "verso": "Material: exige o resultado naturalístico para se consumar (homicídio). Formal: o resultado pode ocorrer, mas não é exigido (extorsão). Mera conduta: não há resultado naturalístico (violação de domicílio).", "explicacao": "Classificação doutrinária. Súmula 96 do STJ: a extorsão se consuma independentemente da vantagem."}, {"id": 2000003057, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "O que é crime omissivo impróprio (comissivo por omissão)?", "verso": "Quando quem tem o dever de agir para evitar o resultado se omite e responde pelo resultado, como se o tivesse causado.", "explicacao": "CP, art. 13, § 2º: dever legal, quem assumiu a responsabilidade e quem criou o risco."}, {"id": 2000003058, "trilha": "policial", "materia": "pen", "assunto": "Princípios", "tipo": "pergunta", "frente": "Cabe princípio da insignificância nos crimes contra a Administração Pública, segundo o STJ?", "verso": "Não, em regra.", "explicacao": "Súmula 599 do STJ. A exceção aceita é o descaminho, conforme o valor do tributo."}, {"id": 2000003059, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pares", "frente": "Qual a diferença entre notitia criminis e delatio criminis?", "verso": "Notitia criminis: conhecimento do crime pela autoridade, por qualquer meio. Delatio criminis: comunicação do crime feita por qualquer pessoa do povo à autoridade.", "explicacao": "CPP, art. 5º, § 3º."}, {"id": 2000003060, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Nos crimes de ação pública condicionada, o inquérito pode ser instaurado sem representação?", "verso": "Não. Depende da representação da vítima ou de requisição do Ministro da Justiça, conforme o caso.", "explicacao": "CPP, art. 5º, § 4º."}, {"id": 2000003061, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O defensor pode ter acesso aos autos do inquérito?", "verso": "Sim, aos elementos de prova já documentados, no interesse do representado.", "explicacao": "Súmula Vinculante 14. Diligências em andamento podem ficar sob sigilo."}, {"id": 2000003062, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "certo_errado", "frente": "Certo ou errado? Vícios ocorridos no inquérito policial anulam automaticamente a ação penal.", "verso": "Errado. Em regra, eventuais irregularidades no inquérito não contaminam a ação penal.", "explicacao": "Entendimento consolidado do STF e do STJ: o inquérito é peça informativa."}, {"id": 2000003063, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "A confissão do acusado supre o exame de corpo de delito?", "verso": "Não. Quando a infração deixa vestígios, o exame é indispensável, direto ou indireto.", "explicacao": "CPP, art. 158."}, {"id": 2000003064, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "A interceptação telefônica é admitida para quais crimes?", "verso": "Para crimes punidos com reclusão, havendo indícios razoáveis de autoria e quando a prova não puder ser feita por outros meios.", "explicacao": "Lei 9.296/1996, art. 2º."}, {"id": 2000003065, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Qual o prazo da interceptação telefônica?", "verso": "15 dias, renovável por igual tempo, uma vez comprovada a indispensabilidade.", "explicacao": "Lei 9.296/1996, art. 5º. Os tribunais admitem renovações sucessivas fundamentadas."}, {"id": 2000003066, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem pode determinar a interceptação telefônica?", "verso": "Só o juiz, de ofício ou a requerimento da autoridade policial (na investigação) ou do Ministério Público.", "explicacao": "Lei 9.296/1996, art. 3º, e CF, art. 5º, XII."}, {"id": 2000003067, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pares", "frente": "Qual a diferença entre flagrante preparado e flagrante esperado?", "verso": "Preparado: o agente é induzido a praticar o crime, e a polícia impede a consumação (crime impossível, ilegal). Esperado: a polícia sabe do crime e apenas aguarda para agir (válido).", "explicacao": "Súmula 145 do STF."}, {"id": 2000003068, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "O que é o flagrante diferido (ação controlada)?", "verso": "O retardamento da intervenção policial sobre a ação da organização criminosa, mantida sob observação, para agir no momento mais eficaz para a prova.", "explicacao": "Lei 12.850/2013, art. 8º. Deve ser comunicado previamente ao juiz."}, {"id": 2000003069, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "Em quanto tempo o auto de prisão em flagrante deve ser enviado ao juiz?", "verso": "Em até 24 horas, e, se o autuado não informar advogado, cópia vai à Defensoria Pública.", "explicacao": "CPP, art. 306, § 1º."}, {"id": 2000003070, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "O que o juiz pode decidir na audiência de custódia?", "verso": "Relaxar a prisão ilegal, converter o flagrante em preventiva (se presentes os requisitos e insuficientes outras medidas) ou conceder liberdade provisória, com ou sem fiança.", "explicacao": "CPP, art. 310."}, {"id": 2000003071, "trilha": "policial", "materia": "ppen", "assunto": "Prisão temporária", "tipo": "pergunta", "frente": "A prisão temporária pode ser decretada durante a ação penal?", "verso": "Não. Só cabe durante a investigação.", "explicacao": "Lei 7.960/1989, art. 1º."}, {"id": 2000003072, "trilha": "policial", "materia": "ppen", "assunto": "Fiança", "tipo": "pergunta", "frente": "Inafiançável significa que o preso não pode ter liberdade provisória?", "verso": "Não. Ele pode obter liberdade provisória sem fiança, se ausentes os requisitos da preventiva.", "explicacao": "Entendimento do STF. A vedação é só à fiança."}, {"id": 2000003073, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Qual o prazo para o Ministério Público oferecer a denúncia?", "verso": "5 dias se o réu estiver preso e 15 dias se estiver solto.", "explicacao": "CPP, art. 46."}, {"id": 2000003074, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "O que é o princípio da indivisibilidade da ação penal privada?", "verso": "A queixa contra um dos autores obriga ao processo de todos, e o MP velará por isso.", "explicacao": "CPP, art. 48. Renúncia em relação a um se estende a todos (art. 49)."}, {"id": 2000003075, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Não sendo conhecido o lugar da infração, como se define a competência?", "verso": "Pelo domicílio ou residência do réu.", "explicacao": "CPP, art. 72."}, {"id": 2000003076, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Na conexão entre crime de competência do júri e crime comum, qual juízo prevalece?", "verso": "O Tribunal do Júri.", "explicacao": "CPP, art. 78, I."}, {"id": 2000003077, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Compete à Justiça Federal julgar crime praticado contra funcionário público federal?", "verso": "Sim, quando relacionado ao exercício da função.", "explicacao": "Súmula 147 do STJ."}, {"id": 2000003078, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quantos jurados são sorteados para a sessão e quantos formam o Conselho de Sentença?", "verso": "25 são sorteados e 7 formam o Conselho de Sentença.", "explicacao": "CPP, arts. 433 e 467."}, {"id": 2000003079, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quando cabe absolvição sumária no procedimento do júri?", "verso": "Quando provada a inexistência do fato, provado não ser o réu autor ou partícipe, o fato não constituir crime ou demonstrada causa de isenção de pena ou de exclusão do crime.", "explicacao": "CPP, art. 415."}, {"id": 2000003080, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual o recurso cabível contra a decisão que rejeita a denúncia?", "verso": "Recurso em sentido estrito.", "explicacao": "CPP, art. 581, I. No Juizado Especial, cabe apelação (Lei 9.099/1995, art. 82)."}, {"id": 2000003081, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Quando cabe a citação por hora certa?", "verso": "Quando o réu se oculta para não ser citado.", "explicacao": "CPP, art. 362."}, {"id": 2000003082, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Quando o juiz deve absolver sumariamente o réu no procedimento comum?", "verso": "Existência manifesta de causa excludente da ilicitude ou da culpabilidade (salvo inimputabilidade), fato que evidentemente não constitui crime ou extinção da punibilidade.", "explicacao": "CPP, art. 397."}, {"id": 2000003083, "trilha": "policial", "materia": "ppen", "assunto": "Nulidades", "tipo": "pergunta", "frente": "A falta de defesa no processo penal gera que tipo de nulidade?", "verso": "Nulidade absoluta. A deficiência da defesa só anula se houver prova de prejuízo.", "explicacao": "Súmula 523 do STF."}, {"id": 2000003084, "trilha": "policial", "materia": "ppen", "assunto": "Nulidades", "tipo": "pergunta", "frente": "Qual o princípio que impede declarar nulidade sem prejuízo?", "verso": "Pas de nullité sans grief: nenhum ato será declarado nulo se não resultar prejuízo para a acusação ou a defesa.", "explicacao": "CPP, art. 563."}, {"id": 2000003085, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "O que é a transação penal?", "verso": "Proposta do MP de aplicação imediata de pena restritiva de direitos ou multa, em infração de menor potencial ofensivo, sem processo.", "explicacao": "Lei 9.099/1995, art. 76."}, {"id": 2000003086, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Na infração de menor potencial ofensivo, cabe prisão em flagrante?", "verso": "Não se impõe a prisão nem se exige fiança se o autor for encaminhado ao Juizado ou assumir o compromisso de comparecer.", "explicacao": "Lei 9.099/1995, art. 69, parágrafo único. Lavra-se termo circunstanciado."}, {"id": 2000003087, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "O que é o termo circunstanciado de ocorrência (TCO)?", "verso": "O registro simplificado feito pela autoridade policial nas infrações de menor potencial ofensivo, no lugar do inquérito.", "explicacao": "Lei 9.099/1995, art. 69."}, {"id": 2000003088, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "A Lei 9.099/1995 se aplica aos crimes de violência doméstica contra a mulher?", "verso": "Não, independentemente da pena.", "explicacao": "Lei 11.340/2006, art. 41, e Súmula 536 do STJ."}, {"id": 2000003089, "trilha": "policial", "materia": "ppen", "assunto": "Interrogatório", "tipo": "pergunta", "frente": "O silêncio do acusado no interrogatório pode ser interpretado em seu prejuízo?", "verso": "Não.", "explicacao": "CPP, art. 186, parágrafo único, e CF, art. 5º, LXIII."}, {"id": 2000003090, "trilha": "policial", "materia": "ppen", "assunto": "Medidas assecuratórias", "tipo": "pares", "frente": "Qual a diferença entre sequestro e arresto no processo penal?", "verso": "Sequestro: recai sobre bens adquiridos com o proveito do crime. Arresto: recai sobre bens lícitos do acusado, para garantir a reparação do dano e as despesas.", "explicacao": "CPP, arts. 125 e 137."}, {"id": 2000003091, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Qual o prazo da infiltração de agentes na Lei de Organizações Criminosas?", "verso": "Até 6 meses, renováveis, desde que comprovada a necessidade, sem exceder 720 dias no total.", "explicacao": "Lei 12.850/2013, art. 10, § 3º."}, {"id": 2000003092, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Quem pode celebrar o acordo de colaboração premiada?", "verso": "O Ministério Público e o delegado de polícia (este na fase de inquérito, com manifestação do MP), com homologação judicial.", "explicacao": "Lei 12.850/2013, art. 4º, §§ 2º e 6º. O STF validou a legitimidade do delegado (ADI 5.508)."}, {"id": 2000003093, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem deve preservar o local do crime até a chegada dos peritos?", "verso": "A autoridade policial, que deve dirigir-se ao local e providenciar para que não se alterem o estado e a conservação das coisas.", "explicacao": "CPP, art. 6º, I."}, {"id": 2000003094, "trilha": "policial", "materia": "ppen", "assunto": "Identificação", "tipo": "pergunta", "frente": "O civilmente identificado pode ser submetido a identificação criminal?", "verso": "Só nas hipóteses previstas em lei, como documento rasurado, insuficiente ou com indício de falsificação, ou quando essencial às investigações por decisão judicial.", "explicacao": "CF, art. 5º, LVIII, e Lei 12.037/2009, art. 3º."}, {"id": 2000003095, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "certo_errado", "frente": "Certo ou errado? A representação da vítima é retratável até o oferecimento da denúncia.", "verso": "Certo.", "explicacao": "CPP, art. 25. Na Lei Maria da Penha, a renúncia só é admitida perante o juiz, em audiência (art. 16)."}, {"id": 2000003096, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Que lesão produz um instrumento cortocontundente, como machado ou facão?", "verso": "Ferida cortocontusa: age pelo gume e pelo peso, com bordas irregulares e possível lesão óssea.", "explicacao": "Classificação dos instrumentos pela forma de ação."}, {"id": 2000003097, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Que lesão produz um instrumento perfurocontundente?", "verso": "Ferida perfurocontusa, como a produzida pelo projétil de arma de fogo.", "explicacao": "Age por pressão em ponto (perfura) e por contusão (empurra os tecidos)."}, {"id": 2000003098, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Que lesão produz o instrumento perfurante, como agulha ou prego?", "verso": "Ferida punctiforme (puntiforme), de pequena abertura e profundidade maior que a largura.", "explicacao": "Lei de Filhos e Langer: as feridas acompanham as linhas de força da pele."}, {"id": 2000003099, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que diz a Lei de Langer sobre as feridas por instrumento perfurante?", "verso": "Instrumentos perfurantes de médio calibre produzem feridas em forma de botoeira, orientadas segundo as linhas de força da pele.", "explicacao": "Por isso a ferida pode lembrar uma lesão de instrumento cortante."}, {"id": 2000003100, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que é fratura em \"galho verde\"?", "verso": "Fratura incompleta, típica de ossos de crianças, em que o osso dobra e quebra só de um lado.", "explicacao": "Os ossos infantis são mais flexíveis."}, {"id": 2000003101, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que são lesões \"em saca-bocado\" no crânio?", "verso": "Fraturas que reproduzem o formato do instrumento contundente, como a cabeça de um martelo.", "explicacao": "Ajudam a identificar o instrumento usado."}, {"id": 2000003102, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que é a \"lesão em espelho\" no tiro?", "verso": "Na ferida de saída, as bordas ficam evertidas (viradas para fora); na de entrada, invertidas.", "explicacao": "Ajuda a determinar a trajetória do projétil."}, {"id": 2000003103, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é o sinal de Werkgaertner?", "verso": "A marca da boca do cano e da massa de mira impressa na pele no tiro encostado.", "explicacao": "Indica disparo com o cano encostado ou muito próximo."}, {"id": 2000003104, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é a câmara de mina de Hoffmann?", "verso": "Lesão em forma de cratera, com bordas laceradas, no tiro encostado sobre região com osso logo abaixo da pele, como o crânio.", "explicacao": "Os gases se expandem entre a pele e o osso e rasgam o tecido."}, {"id": 2000003105, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é o sinal de Benassi?", "verso": "Depósito de fuligem no osso, na região da entrada, em tiro encostado no crânio.", "explicacao": "Confirma o tiro encostado mesmo em cadáver em decomposição."}, {"id": 2000003106, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é a orla de escoriação (de contusão)?", "verso": "Anel em torno do orifício de entrada, causado pelo atrito do projétil que arranca a epiderme.", "explicacao": "Está presente em tiros de qualquer distância."}, {"id": 2000003107, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é a orla de enxugo?", "verso": "Faixa escura em torno do orifício de entrada, formada pelas impurezas que o projétil deixa ao limpar-se na pele.", "explicacao": "Fica por dentro da orla de escoriação."}, {"id": 2000003108, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pares", "frente": "O que diferencia o tiro a curta distância do tiro a distância?", "verso": "No tiro a curta distância, além das orlas, aparecem os efeitos secundários do disparo: zona de tatuagem, de esfumaçamento e de queimadura. No tiro a distância, só os efeitos primários do projétil.", "explicacao": "Os efeitos secundários vêm da pólvora, da fumaça e da chama."}, {"id": 2000003109, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "Por que a zona de esfumaçamento pode ser removida com lavagem, e a de tatuagem não?", "verso": "Porque a fuligem do esfumaçamento fica depositada na superfície, enquanto os grãos de pólvora da tatuagem penetram na pele.", "explicacao": "Diferença usada para estimar a distância do tiro."}, {"id": 2000003110, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que é o exame residuográfico?", "verso": "Pesquisa de resíduos do disparo (chumbo, bário e antimônio) nas mãos do suspeito.", "explicacao": "Indica contato com disparo, mas não prova sozinho a autoria."}, {"id": 2000003111, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Quando costuma surgir a mancha verde abdominal e onde?", "verso": "Entre 18 e 24 horas após a morte, na fossa ilíaca direita.", "explicacao": "É o sinal do início da putrefação no período cromático."}, {"id": 2000003112, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Quais as fases da putrefação?", "verso": "Cromática (coloração), gasosa (enfisema, circulação póstuma), coliquativa (dissolução dos tecidos) e esqueletização.", "explicacao": "Fenômeno transformativo destrutivo."}, {"id": 2000003113, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a circulação póstuma de Brouardel?", "verso": "Desenho das veias superficiais pela pele, em tom esverdeado ou arroxeado, na fase gasosa da putrefação.", "explicacao": "Os gases empurram o sangue para a periferia."}, {"id": 2000003114, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a saponificação (adipocera)?", "verso": "Transformação da gordura do cadáver em substância semelhante a sabão, em ambiente úmido e pouco arejado.", "explicacao": "Fenômeno transformativo conservador."}, {"id": 2000003115, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a mumificação?", "verso": "Desidratação rápida do cadáver em ambiente quente, seco e arejado, que conserva as formas do corpo.", "explicacao": "Fenômeno transformativo conservador."}, {"id": 2000003116, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a maceração?", "verso": "Amolecimento dos tecidos do cadáver imerso em líquido, comum no feto morto retido no útero.", "explicacao": "Pode ser séptica (meio contaminado) ou asséptica (feto)."}, {"id": 2000003117, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a fauna cadavérica e para que serve?", "verso": "Insetos que colonizam o cadáver em ondas sucessivas. A entomologia forense usa essa sucessão para estimar o tempo de morte.", "explicacao": "Ex.: moscas aparecem primeiro."}, {"id": 2000003118, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a morte súbita?", "verso": "Morte natural inesperada, em pessoa aparentemente sadia, em curto espaço de tempo.", "explicacao": "Exige necropsia para afastar causa violenta."}, {"id": 2000003119, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é premoriência?", "verso": "Quando se consegue provar que uma pessoa morreu antes da outra.", "explicacao": "Na impossibilidade de provar, presume-se a comoriência (CC, art. 8º)."}, {"id": 2000003120, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "Como é o sulco no estrangulamento?", "verso": "Horizontal, contínuo, de profundidade uniforme e geralmente abaixo da cartilagem tireoide.", "explicacao": "Diferente do enforcamento, em que o sulco é oblíquo e interrompido no nó."}, {"id": 2000003121, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "Qual a característica da esganadura?", "verso": "É feita com as mãos e não deixa sulco, mas marcas de unhas (estigmas ungueais) e equimoses no pescoço.", "explicacao": "É sempre homicida: não há esganadura suicida."}, {"id": 2000003122, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é o afogado \"branco\" e o \"azul\"?", "verso": "Azul: morte por asfixia, com água nos pulmões e cianose. Branco: morte rápida por inibição reflexa (síncope), quase sem água nos pulmões.", "explicacao": "Classificação clássica dos afogados."}, {"id": 2000003123, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é a sufocação por compressão torácica?", "verso": "Asfixia em que a compressão do tórax impede os movimentos respiratórios, como em soterramentos ou multidões.", "explicacao": "Também chamada de sufocação indireta."}, {"id": 2000003124, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "O que é o sinal de Lichtenberg?", "verso": "Figura arborescente na pele, em forma de samambaia, deixada pela descarga de raio (fulguração).", "explicacao": "É transitória e pode desaparecer em horas."}, {"id": 2000003125, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pares", "frente": "Qual a diferença entre eletroplessão e fulguração?", "verso": "Eletroplessão: lesão por eletricidade artificial (industrial ou doméstica). Fulguração: lesão por eletricidade natural (raio); se mata, é fulminação.", "explicacao": "A marca elétrica de Jellinek é típica da eletroplessão."}, {"id": 2000003126, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "O que é a \"geladura\"?", "verso": "Lesão produzida pelo frio intenso, que pode evoluir de eritema a necrose.", "explicacao": "Energia de ordem física (termonose pelo frio)."}, {"id": 2000003127, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "O que é a regra dos nove de Wallace?", "verso": "Método para estimar a extensão da queimadura: cada região do corpo adulto equivale a 9% (ou múltiplos) da superfície corporal.", "explicacao": "Cabeça 9%, cada braço 9%, cada perna 18%, tronco anterior 18%, posterior 18%, períneo 1%."}, {"id": 2000003128, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pergunta", "frente": "Qual o prazo do exame complementar para comprovar lesão grave por incapacidade por mais de 30 dias?", "verso": "Logo que decorrido o prazo de 30 dias, contado da data do crime.", "explicacao": "CPP, art. 168, § 2º."}, {"id": 2000003129, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pergunta", "frente": "O que é \"deformidade permanente\" para a lesão gravíssima?", "verso": "Dano estético visível, considerável, irreparável e capaz de causar impressão vexatória.", "explicacao": "CP, art. 129, § 2º, IV. A doutrina e a jurisprudência exigem esses requisitos."}, {"id": 2000003130, "trilha": "policial", "materia": "ml", "assunto": "Sexologia", "tipo": "pergunta", "frente": "O que é hímen complacente?", "verso": "Hímen elástico que permite a conjunção carnal sem se romper.", "explicacao": "Por isso a integridade do hímen não descarta a conjunção carnal."}, {"id": 2000003131, "trilha": "policial", "materia": "ml", "assunto": "Sexologia", "tipo": "pergunta", "frente": "Que exame laboratorial ajuda a comprovar a presença de esperma?", "verso": "A pesquisa de espermatozoides e de fosfatase ácida prostática, além do exame de DNA.", "explicacao": "A ausência de espermatozoides não afasta o ato (ex.: vasectomia)."}, {"id": 2000003132, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Quais os requisitos técnicos de um bom método de identificação?", "verso": "Unicidade, imutabilidade, perenidade, praticabilidade e classificabilidade.", "explicacao": "A datiloscopia atende a todos."}, {"id": 2000003133, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "O que é a queiloscopia?", "verso": "Identificação pelo estudo das impressões dos lábios.", "explicacao": "Método complementar de identificação."}, {"id": 2000003134, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Que estruturas do esqueleto ajudam a estimar a idade?", "verso": "A soldadura das epífises, as suturas cranianas, os dentes e a sínfise púbica.", "explicacao": "Em adultos, a estimativa é aproximada."}, {"id": 2000003135, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pares", "frente": "Qual a diferença entre auto e laudo pericial?", "verso": "Auto: as conclusões são ditadas ao escrivão durante o exame. Laudo: redigido pelos próprios peritos depois do exame.", "explicacao": "Os dois são espécies de relatório médico-legal."}, {"id": 2000003136, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pergunta", "frente": "Qual o prazo para o perito elaborar o laudo?", "verso": "Até 10 dias, prorrogável, em casos excepcionais, a requerimento dos peritos.", "explicacao": "CPP, art. 160, parágrafo único."}, {"id": 2000003137, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pergunta", "frente": "O que é o parecer médico-legal?", "verso": "Resposta de um especialista a consulta sobre questão técnica, em geral sobre laudos já feitos, sem novo exame da vítima.", "explicacao": "A parte mais importante é a discussão."}, {"id": 2000003138, "trilha": "policial", "materia": "ml", "assunto": "Toxicologia", "tipo": "pergunta", "frente": "Qual a principal via de eliminação do álcool pelo organismo?", "verso": "A metabolização no fígado, que responde por mais de 90% da eliminação.", "explicacao": "O restante sai pela urina, pela respiração e pelo suor."}, {"id": 2000003139, "trilha": "policial", "materia": "ml", "assunto": "Toxicologia", "tipo": "pergunta", "frente": "O que caracteriza a intoxicação por cianeto no cadáver?", "verso": "Odor de amêndoas amargas e livores de cor vermelho-viva.", "explicacao": "O cianeto bloqueia a respiração celular."}, {"id": 2000003140, "trilha": "policial", "materia": "ml", "assunto": "Perícia", "tipo": "pergunta", "frente": "O que é perinecroscopia?", "verso": "O exame do local onde o cadáver foi encontrado e de seus arredores.", "explicacao": "Complementa a necropsia e orienta a investigação."}, {"id": 2000003141, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que significa a indivisibilidade dos direitos humanos?", "verso": "Os direitos civis, políticos, econômicos, sociais e culturais formam um todo e devem ser protegidos em conjunto, sem hierarquia entre eles.", "explicacao": "Declaração e Programa de Ação de Viena (1993)."}, {"id": 2000003142, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é o princípio da vedação do retrocesso?", "verso": "Uma vez reconhecido e concretizado um direito, o Estado não pode suprimi-lo ou reduzi-lo sem compensação.", "explicacao": "Também chamado de efeito cliquet."}, {"id": 2000003143, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Qual documento afirmou que todos os direitos humanos são universais, indivisíveis, interdependentes e inter-relacionados?", "verso": "A Declaração e Programa de Ação de Viena, de 1993.", "explicacao": "Conferência Mundial sobre Direitos Humanos da ONU."}, {"id": 2000003144, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "Qual órgão da ONU substituiu a antiga Comissão de Direitos Humanos em 2006?", "verso": "O Conselho de Direitos Humanos da ONU, com sede em Genebra.", "explicacao": "É ele que conduz a Revisão Periódica Universal."}, {"id": 2000003145, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "O que é o Alto Comissariado das Nações Unidas para os Direitos Humanos?", "verso": "O principal órgão da ONU encarregado de promover e proteger os direitos humanos, com sede em Genebra.", "explicacao": "Criado em 1993, após a Conferência de Viena."}, {"id": 2000003146, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "Qual a função do Subcomitê de Prevenção da Tortura da ONU?", "verso": "Visitar locais de privação de liberdade dos Estados que ratificaram o Protocolo Facultativo à Convenção contra a Tortura.", "explicacao": "O protocolo também obriga a criar mecanismos nacionais de prevenção."}, {"id": 2000003147, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Onde ficam a Comissão e a Corte Interamericana de Direitos Humanos?", "verso": "Comissão em Washington (EUA) e Corte em San José (Costa Rica).", "explicacao": "Órgãos do Pacto de São José."}, {"id": 2000003148, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Desde quando o Brasil reconhece a jurisdição contenciosa da Corte Interamericana?", "verso": "Desde 1998, para fatos posteriores a essa data.", "explicacao": "Decreto Legislativo 89/1998."}, {"id": 2000003149, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Em que ano o Brasil aderiu ao Pacto de São José da Costa Rica?", "verso": "Em 1992.", "explicacao": "Decreto 678/1992. O Pacto é de 1969."}, {"id": 2000003150, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o requisito, em regra, para a Comissão Interamericana receber uma petição?", "verso": "O esgotamento dos recursos internos, salvo exceções como demora injustificada ou falta de devido processo.", "explicacao": "Convenção Americana, art. 46."}, {"id": 2000003151, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "O que decidiu a Corte Interamericana no caso Gomes Lund (Guerrilha do Araguaia)?", "verso": "Que a Lei de Anistia não pode impedir a investigação e punição de graves violações de direitos humanos.", "explicacao": "Sentença de 2010 contra o Brasil."}, {"id": 2000003152, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "O que o caso Favela Nova Brasília levou a Corte Interamericana a determinar ao Brasil?", "verso": "Investigar mortes em operações policiais de forma independente e ajustar protocolos de uso da força.", "explicacao": "Sentença de 2017, sobre operações no Rio de Janeiro em 1994 e 1995."}, {"id": 2000003153, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o prazo para levar um caso à Comissão Interamericana após a decisão definitiva interna?", "verso": "6 meses.", "explicacao": "Convenção Americana, art. 46, 1, b."}, {"id": 2000003154, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "Quais os elementos da definição de tortura na Convenção da ONU?", "verso": "Dor ou sofrimento grave, físico ou mental, infligido intencionalmente para obter informação, castigar, intimidar ou discriminar, por agente público ou com sua aquiescência.", "explicacao": "Convenção contra a Tortura (1984), art. 1º."}, {"id": 2000003155, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "Qual a diferença entre o conceito de tortura da Convenção da ONU e o da lei brasileira?", "verso": "Na Convenção, a tortura é praticada por agente público ou com sua concordância. Na Lei 9.455/1997, qualquer pessoa pode praticar tortura (crime comum).", "explicacao": "Ser agente público, no Brasil, é causa de aumento de pena."}, {"id": 2000003156, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Quais são os níveis do uso progressivo da força, em regra?", "verso": "Presença policial, verbalização, controle de contato, técnicas de imobilização, uso de instrumentos de menor potencial ofensivo e força potencialmente letal.", "explicacao": "Modelos de uso diferenciado da força."}, {"id": 2000003157, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "O que é o princípio da proporcionalidade no uso da força?", "verso": "A força usada deve ser compatível com a gravidade da ameaça e com o objetivo legítimo a alcançar.", "explicacao": "Junto com legalidade, necessidade e conveniência (Portaria Interministerial 4.226/2010)."}, {"id": 2000003158, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Após o uso da força que resulte em lesão ou morte, quais deveres o agente tem?", "verso": "Prestar socorro médico, comunicar a autoridade competente e os familiares, e preservar o local.", "explicacao": "Princípios Básicos da ONU e Portaria Interministerial 4.226/2010."}, {"id": 2000003159, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "Qual o objetivo da Convenção sobre os Direitos das Pessoas com Deficiência?", "verso": "Promover, proteger e assegurar o exercício pleno e equitativo dos direitos humanos pelas pessoas com deficiência.", "explicacao": "No Brasil, ela tem status de emenda constitucional (Decreto 6.949/2009)."}, {"id": 2000003160, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "O que são os Princípios de Yogyakarta?", "verso": "Princípios sobre a aplicação do direito internacional dos direitos humanos em relação à orientação sexual e identidade de gênero.", "explicacao": "Documento de 2006, não vinculante."}, {"id": 2000003161, "trilha": "policial", "materia": "dh", "assunto": "Igualdade", "tipo": "pergunta", "frente": "O que decidiu o STF na ADO 26 e no MI 4.733?", "verso": "Que condutas homofóbicas e transfóbicas se enquadram nos crimes da Lei do Racismo (Lei 7.716/1989), até que o Congresso legisle.", "explicacao": "Julgamento de 2019."}, {"id": 2000003162, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Os direitos e garantias expressos na Constituição excluem outros?", "verso": "Não. Não excluem outros decorrentes do regime e dos princípios adotados ou dos tratados internacionais de que o Brasil seja parte.", "explicacao": "CF, art. 5º, § 2º (cláusula de abertura)."}, {"id": 2000003163, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Que status têm os tratados de direitos humanos aprovados sem o rito de emenda constitucional?", "verso": "Status supralegal: abaixo da Constituição e acima das leis.", "explicacao": "STF, RE 466.343 (2008)."}, {"id": 2000003164, "trilha": "policial", "materia": "dh", "assunto": "Crianças", "tipo": "pergunta", "frente": "O que são as Regras de Beijing?", "verso": "Regras Mínimas das Nações Unidas para a Administração da Justiça da Infância e da Juventude.", "explicacao": "Inspiraram o ECA."}, {"id": 2000003165, "trilha": "policial", "materia": "dh", "assunto": "Mulheres", "tipo": "pergunta", "frente": "Quais tipos de violência contra a mulher a Convenção de Belém do Pará reconhece?", "verso": "Física, sexual e psicológica, no âmbito familiar, na comunidade ou perpetrada ou tolerada pelo Estado.", "explicacao": "Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher (1994)."}, {"id": 2000003166, "trilha": "policial", "materia": "dh", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que é a Política Nacional de Segurança Pública e Defesa Social (PNSPDS)?", "verso": "A política criada pela Lei 13.675/2018, junto com o SUSP, para integrar os órgãos de segurança pública.", "explicacao": "Prevê, entre outros, o respeito aos direitos humanos e o uso proporcional da força."}, {"id": 2000003167, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é engenharia social?", "verso": "Técnica de manipular pessoas para que revelem informações ou executem ações, explorando confiança, medo ou pressa.", "explicacao": "Base de golpes como phishing e falsa central de atendimento."}, {"id": 2000003168, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um cavalo de troia (trojan)?", "verso": "Programa que parece legítimo, mas esconde funções maliciosas, como abrir uma porta para o invasor.", "explicacao": "Diferente do vírus, não se replica sozinho."}, {"id": 2000003169, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um backdoor?", "verso": "Uma \"porta dos fundos\": mecanismo que permite ao invasor voltar a acessar o sistema sem passar pela autenticação normal.", "explicacao": "Costuma ser instalado por trojans."}, {"id": 2000003170, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é adware?", "verso": "Programa que exibe propagandas indesejadas, muitas vezes junto com coleta de dados de navegação.", "explicacao": "Pode vir embutido em programas gratuitos."}, {"id": 2000003171, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é smishing e vishing?", "verso": "Smishing: phishing por SMS. Vishing: phishing por voz (ligação telefônica).", "explicacao": "Variações de engenharia social."}, {"id": 2000003172, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é o golpe do falso QR code?", "verso": "Substituir ou enviar um QR code que leva a site falso ou a pagamento para conta do golpista.", "explicacao": "Conferir o destino e o recebedor antes de pagar."}, {"id": 2000003173, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um ataque de força bruta?", "verso": "Tentar todas as combinações possíveis de senha até acertar.", "explicacao": "Senhas longas e bloqueio após tentativas dificultam o ataque."}, {"id": 2000003174, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um exploit?", "verso": "Código ou técnica que se aproveita de uma vulnerabilidade de software para atacar o sistema.", "explicacao": "Atualizações de segurança corrigem as falhas exploradas."}, {"id": 2000003175, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é uma vulnerabilidade de dia zero (zero-day)?", "verso": "Falha desconhecida pelo fabricante e ainda sem correção, que pode ser explorada por atacantes.", "explicacao": "Por isso o nome: zero dias para corrigir."}, {"id": 2000003176, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Qual a diferença entre autenticação e autorização?", "verso": "Autenticação: confirmar quem é o usuário (ex.: senha). Autorização: definir o que ele pode acessar depois de autenticado.", "explicacao": "Conceitos básicos de controle de acesso."}, {"id": 2000003177, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é o princípio do menor privilégio?", "verso": "Cada usuário deve ter apenas os acessos necessários para sua função.", "explicacao": "Reduz danos em caso de invasão ou erro."}, {"id": 2000003178, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que garante o não repúdio?", "verso": "Que o autor de uma mensagem ou transação não possa negar que a fez.", "explicacao": "Garantido pela assinatura digital."}, {"id": 2000003179, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Qual a diferença entre backup completo e diferencial?", "verso": "Completo: copia tudo. Diferencial: copia o que mudou desde o último backup completo, acumulando as mudanças.", "explicacao": "O incremental copia só o que mudou desde o último backup de qualquer tipo."}, {"id": 2000003180, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é a regra 3-2-1 de backup?", "verso": "Ter 3 cópias dos dados, em 2 mídias diferentes, sendo 1 fora do local (ex.: nuvem).", "explicacao": "Boa prática para não perder dados."}, {"id": 2000003181, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que é endereço IP?", "verso": "Número que identifica um dispositivo em uma rede.", "explicacao": "Na internet, o DNS traduz nomes (sites) em endereços IP."}, {"id": 2000003182, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "Qual a função do DHCP?", "verso": "Atribuir automaticamente endereços IP e configurações de rede aos dispositivos.", "explicacao": "Sem ele, seria preciso configurar o IP à mão em cada aparelho."}, {"id": 2000003183, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "Qual a diferença entre LAN, MAN e WAN?", "verso": "LAN: rede local (casa, escritório). MAN: rede de uma cidade. WAN: rede de longa distância, como a internet.", "explicacao": "Classificação por abrangência geográfica."}, {"id": 2000003184, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "Qual a função do protocolo FTP?", "verso": "Transferir arquivos entre computadores na rede.", "explicacao": "Usa, em regra, as portas 20 e 21."}, {"id": 2000003185, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "Qual a porta padrão do HTTPS?", "verso": "443.", "explicacao": "O HTTP usa a porta 80."}, {"id": 2000003186, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que é a deep web e a dark web?", "verso": "Deep web: conteúdo não indexado por buscadores (ex.: e-mails, sistemas internos). Dark web: parte da deep web acessível só com ferramentas específicas, como o Tor.", "explicacao": "A dark web é usada para anonimato, inclusive para crimes."}, {"id": 2000003187, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "O que faz o atalho Ctrl + Shift + T no navegador?", "verso": "Reabre a última aba fechada.", "explicacao": "Funciona no Chrome, no Edge e no Firefox."}, {"id": 2000003188, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "Qual o atalho para abrir uma janela anônima no Chrome?", "verso": "Ctrl + Shift + N.", "explicacao": "No Firefox e no Edge, Ctrl + Shift + P e Ctrl + Shift + N, respectivamente."}, {"id": 2000003189, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "A navegação anônima impede que o provedor ou a empresa veja os sites acessados?", "verso": "Não. Ela só evita guardar histórico, cookies e dados no próprio computador.", "explicacao": "O provedor e a rede ainda podem registrar o tráfego."}, {"id": 2000003190, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a função =MÉDIA(A1:A4)?", "verso": "Calcula a média aritmética dos valores do intervalo.", "explicacao": "Ignora células vazias e textos."}, {"id": 2000003191, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a função =CONT.VALORES(A1:A10)?", "verso": "Conta as células não vazias do intervalo.", "explicacao": "=CONT.NÚM conta só as que têm números."}, {"id": 2000003192, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a referência $A$1 ao copiar a fórmula?", "verso": "Fica fixa: nem a coluna nem a linha mudam.", "explicacao": "$A1 fixa só a coluna; A$1 fixa só a linha."}, {"id": 2000003193, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que significa o erro #N/D no Excel?", "verso": "Que o valor procurado não foi encontrado, comum em PROCV.", "explicacao": "\"Não disponível\"."}, {"id": 2000003194, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "Qual o resultado de =ARRED(3,456;2)?", "verso": "3,46.", "explicacao": "ARRED arredonda para o número de casas indicado."}, {"id": 2000003195, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a função =CONCATENAR(A1;\" \";B1)?", "verso": "Junta o conteúdo de A1, um espaço e o de B1 em um só texto.", "explicacao": "O operador & faz o mesmo: =A1&\" \"&B1."}, {"id": 2000003196, "trilha": "policial", "materia": "inf", "assunto": "Word", "tipo": "pergunta", "frente": "Qual o atalho para centralizar o texto no Word em português?", "verso": "Ctrl + E.", "explicacao": "Ctrl + Q alinha à esquerda, Ctrl + G à direita e Ctrl + J justifica."}, {"id": 2000003197, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "O que faz o atalho Windows + L?", "verso": "Bloqueia o computador.", "explicacao": "Boa prática ao sair da estação de trabalho."}, {"id": 2000003198, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "O que é a Lixeira do Windows?", "verso": "Pasta que guarda temporariamente os arquivos excluídos do disco local, permitindo restaurá-los.", "explicacao": "Arquivos de pen drive ou rede, em geral, não vão para a Lixeira."}, {"id": 2000003199, "trilha": "policial", "materia": "inf", "assunto": "Sistemas", "tipo": "pergunta", "frente": "O que é um sistema operacional?", "verso": "Software que gerencia o hardware e serve de base para os programas, como Windows, Linux, Android e iOS.", "explicacao": "Faz a interface entre o usuário, os aplicativos e o hardware."}, {"id": 2000003200, "trilha": "policial", "materia": "inf", "assunto": "Sistemas", "tipo": "pergunta", "frente": "O que é software livre?", "verso": "Software que garante as liberdades de usar, estudar, modificar e redistribuir o programa, com acesso ao código-fonte.", "explicacao": "Ex.: Linux e LibreOffice. Livre não é o mesmo que gratuito."}, {"id": 2000003201, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "O que é uma proposição simples?", "verso": "Uma frase declarativa que pode ser julgada como verdadeira ou falsa, sem conectivos.", "explicacao": "Perguntas, ordens e exclamações não são proposições."}, {"id": 2000003202, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "certo_errado", "frente": "Certo ou errado? \"Que dia lindo!\" é uma proposição.", "verso": "Errado. Frase exclamativa não pode ser julgada verdadeira ou falsa.", "explicacao": "Também não são proposições: perguntas, ordens e sentenças abertas (\"x + 2 = 5\")."}, {"id": 2000003203, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "O que é uma sentença aberta?", "verso": "Frase com variável, cujo valor lógico depende do valor atribuído (ex.: \"x é maior que 5\").", "explicacao": "Não é proposição enquanto a variável não for definida."}, {"id": 2000003204, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Qual a negação de \"P se e somente se Q\"?", "verso": "\"P ou Q, mas não ambos\" (disjunção exclusiva), ou \"P se e somente se não Q\".", "explicacao": "A bicondicional é verdadeira quando P e Q têm o mesmo valor."}, {"id": 2000003205, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Qual a tabela-verdade da conjunção \"P e Q\"?", "verso": "Só é verdadeira quando P e Q são verdadeiras.", "explicacao": "Basta uma falsa para tudo ser falso."}, {"id": 2000003206, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Qual a tabela-verdade da disjunção inclusiva \"P ou Q\"?", "verso": "Só é falsa quando P e Q são falsas.", "explicacao": "Basta uma verdadeira para tudo ser verdadeiro."}, {"id": 2000003207, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quais as leis de De Morgan?", "verso": "~(P ∧ Q) = ~P ∨ ~Q e ~(P ∨ Q) = ~P ∧ ~Q.", "explicacao": "Negar \"e\" vira \"ou\" com as partes negadas, e vice-versa."}, {"id": 2000003208, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Qual a negação de \"Algum policial não é honesto\"?", "verso": "\"Todo policial é honesto\".", "explicacao": "Negação de \"algum A não é B\" é \"todo A é B\"."}, {"id": 2000003209, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "\"Nenhum A é B\" equivale a quê?", "verso": "\"Todo A não é B\" (ou seja, nenhum elemento de A está em B).", "explicacao": "Os conjuntos A e B não têm elementos em comum."}, {"id": 2000003210, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é a falácia da afirmação do consequente?", "verso": "Concluir P a partir de \"Se P, então Q\" e \"Q\". É um argumento inválido.", "explicacao": "Ex.: Se chove, a rua molha; a rua molhou; logo choveu (pode ter outra causa)."}, {"id": 2000003211, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é a falácia da negação do antecedente?", "verso": "Concluir \"não Q\" a partir de \"Se P, então Q\" e \"não P\". É um argumento inválido.", "explicacao": "Ex.: Se chove, a rua molha; não choveu; logo a rua não molhou."}, {"id": 2000003212, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é o silogismo disjuntivo?", "verso": "De \"P ou Q\" e \"não P\", conclui-se Q.", "explicacao": "Argumento válido."}, {"id": 2000003213, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é o silogismo hipotético?", "verso": "De \"Se P, então Q\" e \"Se Q, então R\", conclui-se \"Se P, então R\".", "explicacao": "Argumento válido (transitividade da condicional)."}, {"id": 2000003214, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos anagramas tem a palavra BALA?", "verso": "12.", "explicacao": "4! ÷ 2! = 24 ÷ 2 = 12 (a letra A se repete duas vezes)."}, {"id": 2000003215, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantas comissões de 3 pessoas podem ser formadas com 10 pessoas?", "verso": "120.", "explicacao": "C(10,3) = 10 × 9 × 8 ÷ 6 = 120."}, {"id": 2000003216, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantas senhas de 4 dígitos (0 a 9) podem ser formadas, permitindo repetição?", "verso": "10.000.", "explicacao": "10 × 10 × 10 × 10 = 10⁴."}, {"id": 2000003217, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quanto vale 0! (zero fatorial)?", "verso": "1.", "explicacao": "Por definição."}, {"id": 2000003218, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de sair cara duas vezes em dois lançamentos de uma moeda honesta?", "verso": "1/4.", "explicacao": "1/2 × 1/2 = 1/4 (eventos independentes)."}, {"id": 2000003219, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de tirar um número maior que 4 em um dado comum?", "verso": "1/3.", "explicacao": "Os números 5 e 6: 2 de 6 resultados = 1/3."}, {"id": 2000003220, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a fórmula da probabilidade de \"A ou B\" quando os eventos não são exclusivos?", "verso": "P(A ∪ B) = P(A) + P(B) − P(A ∩ B).", "explicacao": "Subtrai-se a interseção para não contá-la duas vezes."}, {"id": 2000003221, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Um preço subiu de R$ 50 para R$ 60. Qual o aumento percentual?", "verso": "20%.", "explicacao": "(60 − 50) ÷ 50 = 0,2."}, {"id": 2000003222, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Dois aumentos sucessivos de 10% equivalem a um aumento único de quanto?", "verso": "21%.", "explicacao": "1,1 × 1,1 = 1,21."}, {"id": 2000003223, "trilha": "policial", "materia": "rl", "assunto": "Juros", "tipo": "pergunta", "frente": "Qual o montante de R$ 1.000 a juros compostos de 10% ao ano por 2 anos?", "verso": "R$ 1.210.", "explicacao": "1.000 × 1,1² = 1.210. Com juros simples seria R$ 1.200."}, {"id": 2000003224, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o próximo termo de 2, 6, 18, 54, …?", "verso": "162.", "explicacao": "PG de razão 3: 54 × 3."}, {"id": 2000003225, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual a soma dos 10 primeiros termos da PA 1, 2, 3, …, 10?", "verso": "55.", "explicacao": "Sn = (a1 + an) × n ÷ 2 = (1 + 10) × 10 ÷ 2."}, {"id": 2000003226, "trilha": "policial", "materia": "rl", "assunto": "Conjuntos", "tipo": "pergunta", "frente": "Em uma turma, 20 estudam Penal, 15 Processo Penal e 5 as duas matérias. Quantos estudam pelo menos uma?", "verso": "30.", "explicacao": "n(A ∪ B) = 20 + 15 − 5."}, {"id": 2000003227, "trilha": "policial", "materia": "rl", "assunto": "Proporção", "tipo": "pergunta", "frente": "Se 3 viaturas consomem 60 litros em um dia, quantos litros 5 viaturas consomem no mesmo período?", "verso": "100 litros.", "explicacao": "Regra de três direta: 60 ÷ 3 × 5."}, {"id": 2000003228, "trilha": "policial", "materia": "rl", "assunto": "Frações", "tipo": "pergunta", "frente": "Quanto é 2/3 de 3/4 de 120?", "verso": "60.", "explicacao": "3/4 de 120 = 90; 2/3 de 90 = 60."}, {"id": 2000003229, "trilha": "policial", "materia": "rl", "assunto": "Calendário", "tipo": "pergunta", "frente": "Se 1º de março caiu numa sexta-feira, em que dia da semana cai 31 de março do mesmo ano?", "verso": "Domingo.", "explicacao": "De 1º a 31 são 30 dias: 30 = 4 semanas + 2 dias. Sexta + 2 = domingo."}, {"id": 2000003230, "trilha": "policial", "materia": "rl", "assunto": "Média", "tipo": "pergunta", "frente": "A média de 4 números é 10. Retirando-se um deles, a média dos 3 restantes passa a ser 9. Qual número foi retirado?", "verso": "13.", "explicacao": "Soma de 4 = 40; soma de 3 = 27; 40 − 27 = 13."}, {"id": 2000003231, "trilha": "policial", "materia": "rl", "assunto": "MMC e MDC", "tipo": "pergunta", "frente": "Qual o MMC de 6, 8 e 12?", "verso": "24.", "explicacao": "Menor número divisível por 6, 8 e 12."}, {"id": 2000003232, "trilha": "policial", "materia": "rl", "assunto": "MMC e MDC", "tipo": "pergunta", "frente": "Qual o MDC de 36 e 48?", "verso": "12.", "explicacao": "Maior número que divide os dois."}, {"id": 2000003233, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "\"Bastante\" varia quando é adjetivo?", "verso": "Sim. \"Há provas bastantes\" (suficientes). Como advérbio, não varia: \"Elas são bastante dedicadas\".", "explicacao": "Se puder trocar por \"muitos/suficientes\", varia; se por \"muito\", não."}, {"id": 2000003234, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "\"Anexo\" e \"incluso\" concordam com o substantivo?", "verso": "Sim. \"Seguem anexas as fotos\"; \"Vai inclusa a certidão\". A expressão \"em anexo\" não varia.", "explicacao": "São adjetivos."}, {"id": 2000003235, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "\"Menos\" varia?", "verso": "Não. O certo é \"menos pessoas\", nunca \"menas\".", "explicacao": "\"Menos\" é invariável."}, {"id": 2000003236, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "\"Pseudo\" varia?", "verso": "Não. \"Os pseudo-heróis\", \"a pseudo-testemunha\".", "explicacao": "É prefixo."}, {"id": 2000003237, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Como concorda o verbo \"ser\" em \"Hoje são 15 de maio\" e \"Hoje é 15 de maio\"?", "verso": "Ambas são aceitas: o verbo concorda com o numeral (\"são 15\") ou com a palavra \"dia\" subentendida (\"é dia 15\").", "explicacao": "Nas indicações de hora e distância, concorda com o numeral: \"São 3 horas\"."}, {"id": 2000003238, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Na expressão \"Mais de dois\", o verbo fica em que número?", "verso": "No plural: \"Mais de dois policiais chegaram\".", "explicacao": "O verbo concorda com o numeral."}, {"id": 2000003239, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Em \"Tu e ele sairão\" ou \"Tu e ele saireis\", qual está de acordo com a norma?", "verso": "As duas são aceitas: a 2ª pessoa prevalece sobre a 3ª, mas admite-se a 3ª do plural.", "explicacao": "Com \"eu\" no sujeito, o verbo vai para a 1ª do plural."}, {"id": 2000003240, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "\"Morar\" e \"residir\" pedem qual preposição?", "verso": "\"Em\": \"Moro na Rua X\", e não \"à Rua X\".", "explicacao": "Também \"situado em\" e \"estabelecido em\"."}, {"id": 2000003241, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "\"Proceder\" no sentido de dar início pede preposição?", "verso": "Sim, \"a\": \"O delegado procedeu ao interrogatório\".", "explicacao": "No sentido de ter fundamento, não pede: \"A queixa procede\"."}, {"id": 2000003242, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "\"Ir\" pede qual preposição para indicar destino?", "verso": "\"A\" ou \"para\": \"Fui à delegacia\", \"Fui para casa\". Não se usa \"em\": \"Fui no banco\" é coloquial.", "explicacao": "\"A\" indica ida passageira; \"para\", permanência."}, {"id": 2000003243, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "\"Avisar\" admite quais construções?", "verso": "Avisar alguém de algo ou avisar algo a alguém: \"Avisei o preso do horário\" ou \"Avisei o horário ao preso\".", "explicacao": "Não se usam os dois objetos indiretos ao mesmo tempo."}, {"id": 2000003244, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "\"Custar\" no sentido de ser difícil: como se usa?", "verso": "A coisa difícil é o sujeito: \"Custou-me entender o caso\". Na norma-padrão, evita-se \"Eu custei a entender\".", "explicacao": "Regência tradicional."}, {"id": 2000003245, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Há crase antes de pronome de tratamento?", "verso": "Em regra não: \"Encaminho a Vossa Senhoria\". Exceção: senhora, senhorita e dona.", "explicacao": "Esses pronomes não admitem artigo."}, {"id": 2000003246, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Há crase em \"Fui à Bahia\" e em \"Fui a Brasília\"?", "verso": "Sim em \"à Bahia\" (volto da Bahia) e não em \"a Brasília\" (volto de Brasília).", "explicacao": "Regra do \"volto da / volto de\"."}, {"id": 2000003247, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Há crase na expressão \"a distância\"?", "verso": "Só quando a distância é determinada: \"Ficou à distância de 50 metros\". Indeterminada, em regra não: \"Ensino a distância\".", "explicacao": "Muitas bancas aceitam a crase nos dois casos; a regra acima é a mais cobrada."}, {"id": 2000003248, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Há crase antes de \"aquele\", \"aquela\" e \"aquilo\"?", "verso": "Sim, quando o termo anterior exige a preposição \"a\": \"Referiu-se àquele caso\".", "explicacao": "A + aquele = àquele."}, {"id": 2000003249, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Usa-se vírgula para separar orações coordenadas assindéticas?", "verso": "Sim: \"Chegou, viu, prendeu\".", "explicacao": "Assindéticas são as orações ligadas sem conjunção."}, {"id": 2000003250, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Para que servem os dois-pontos?", "verso": "Para introduzir citação, enumeração, explicação ou esclarecimento.", "explicacao": "Ex.: \"Apreendeu três itens: arma, droga e dinheiro\"."}, {"id": 2000003251, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Usa-se vírgula antes de \"etc.\"?", "verso": "Pelo Acordo e pela tradição, a vírgula é facultativa; a forma mais comum é usá-la.", "explicacao": "\"etc.\" já significa \"e outras coisas\"."}, {"id": 2000003252, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Escreve-se \"excesso\" ou \"exceço\"? E \"exceção\"?", "verso": "\"Excesso\" (com ss) e \"exceção\" (com ç).", "explicacao": "Pares parecidos que caem em prova."}, {"id": 2000003253, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Escreve-se \"privilégio\" ou \"previlégio\"?", "verso": "\"Privilégio\".", "explicacao": "Também \"privilegiado\", como no homicídio privilegiado."}, {"id": 2000003254, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Escreve-se \"reivindicar\" ou \"reinvindicar\"?", "verso": "\"Reivindicar\".", "explicacao": "Erro frequente em prova de ortografia."}, {"id": 2000003255, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Escreve-se \"impecilho\" ou \"empecilho\"?", "verso": "\"Empecilho\".", "explicacao": "Vem de \"empecer\"."}, {"id": 2000003256, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Escreve-se \"beneficente\" ou \"beneficiente\"?", "verso": "\"Beneficente\".", "explicacao": "Também \"beneficência\"."}, {"id": 2000003257, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Qual a diferença entre \"cessão\", \"sessão\" e \"seção\"?", "verso": "Cessão: ato de ceder. Sessão: reunião ou tempo de duração. Seção: divisão, departamento.", "explicacao": "\"Secção\" também é aceita para divisão."}, {"id": 2000003258, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Qual a diferença entre \"despensa\" e \"dispensa\"?", "verso": "Despensa: lugar onde se guardam alimentos. Dispensa: licença, liberação.", "explicacao": "Parônimos."}, {"id": 2000003259, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Qual a diferença entre \"emergir\" e \"imergir\"?", "verso": "Emergir: vir à tona. Imergir: mergulhar, afundar.", "explicacao": "Parônimos."}, {"id": 2000003260, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Qual a diferença entre \"tachar\" e \"taxar\"?", "verso": "Tachar: atribuir defeito, rotular (\"tacharam-no de corrupto\"). Taxar: fixar taxa ou imposto.", "explicacao": "Homônimos homófonos."}, {"id": 2000003261, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Qual a diferença entre \"conserto\" e \"concerto\"?", "verso": "Conserto: reparo. Concerto: apresentação musical ou acordo.", "explicacao": "Homônimos homófonos."}, {"id": 2000003262, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "Por que \"saída\" e \"saúde\" têm acento?", "verso": "Porque o i e o u tônicos formam hiato com a vogal anterior e estão sozinhos na sílaba (ou com s).", "explicacao": "Regra do hiato."}, {"id": 2000003263, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "\"Para\" (verbo) ainda tem acento diferencial?", "verso": "Não. Desde o Acordo Ortográfico, \"para\" (verbo) não leva acento.", "explicacao": "Mantiveram o acento diferencial \"pôde\" (passado) e \"pôr\" (verbo)."}, {"id": 2000003264, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "Por que \"júri\" e \"táxi\" têm acento?", "verso": "Porque são paroxítonas terminadas em i.", "explicacao": "Paroxítonas terminadas em i, is, us, um, uns, l, n, r, x, ps e ditongo são acentuadas."}, {"id": 2000003265, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Qual a classe da palavra \"onde\" em \"A casa onde mora\"?", "verso": "Pronome relativo (ou advérbio relativo), equivalente a \"em que\".", "explicacao": "Retoma \"casa\"."}, {"id": 2000003266, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Em \"Ele age rápido\", qual a classe de \"rápido\"?", "verso": "Advérbio (adjetivo adverbializado), equivalente a \"rapidamente\".", "explicacao": "Por isso não varia: \"Elas agem rápido\"."}, {"id": 2000003267, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Qual a função de \"ao delegado\" em \"O escrivão entregou o inquérito ao delegado\"?", "verso": "Objeto indireto.", "explicacao": "\"O inquérito\" é objeto direto."}, {"id": 2000003268, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Qual a função de \"pela polícia\" em \"O suspeito foi preso pela polícia\"?", "verso": "Agente da passiva.", "explicacao": "Na voz ativa, seria o sujeito: \"A polícia prendeu o suspeito\"."}, {"id": 2000003269, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "O que é predicativo do sujeito?", "verso": "Termo que atribui uma característica ao sujeito por meio de verbo de ligação: \"O réu está nervoso\".", "explicacao": "Verbos de ligação: ser, estar, parecer, permanecer, ficar, continuar."}, {"id": 2000003270, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Qual o sujeito em \"Precisa-se de agentes\"?", "verso": "Indeterminado.", "explicacao": "Com verbo transitivo indireto + \"se\", o sujeito é indeterminado e o verbo fica no singular."}, {"id": 2000003271, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Qual a forma correta: \"Se ele manter\" ou \"Se ele mantiver\"?", "verso": "\"Se ele mantiver\".", "explicacao": "\"Manter\" segue \"ter\": tiver, mantiver, detiver, obtiver."}, {"id": 2000003272, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Qual a forma correta: \"Quando eu vir\" ou \"Quando eu ver\" (verbo ver)?", "verso": "\"Quando eu vir\".", "explicacao": "Futuro do subjuntivo de \"ver\": vir, vires, vir, virmos, virdes, virem."}, {"id": 2000003273, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Qual o particípio de \"prender\" usado com \"ter\" e com \"ser\"?", "verso": "Com \"ter\", \"prendido\"; com \"ser\" ou \"estar\", \"preso\".", "explicacao": "\"O policial tinha prendido\"; \"O suspeito foi preso\"."}, {"id": 2000003274, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pares", "frente": "Qual a diferença entre inferência e extrapolação na interpretação de texto?", "verso": "Inferência: conclusão que o texto autoriza, mesmo sem dizer. Extrapolação: ir além do texto, acrescentando ideias que ele não sustenta.", "explicacao": "Extrapolação é erro comum nas alternativas."}, {"id": 2000003275, "trilha": "policial", "materia": "port", "assunto": "Coesão", "tipo": "pergunta", "frente": "O que é a coesão referencial?", "verso": "A retomada ou antecipação de termos por pronomes, sinônimos ou expressões, evitando repetição.", "explicacao": "Ex.: \"O delegado chegou. Ele pediu os autos.\""}, {"id": 2000003276, "trilha": "policial", "materia": "port", "assunto": "Redação oficial", "tipo": "pergunta", "frente": "Qual o pronome de tratamento usado para o Presidente da República?", "verso": "Vossa Excelência.", "explicacao": "Vocativo: \"Excelentíssimo Senhor Presidente da República\"."}, {"id": 2000003277, "trilha": "policial", "materia": "port", "assunto": "Redação oficial", "tipo": "pergunta", "frente": "Com pronome de tratamento (\"Vossa Senhoria\"), o verbo e o possessivo ficam em que pessoa?", "verso": "Na 3ª pessoa: \"Vossa Senhoria informou seu endereço\".", "explicacao": "Nunca \"vosso\"."}, {"id": 2000003278, "trilha": "policial", "materia": "port", "assunto": "Redação oficial", "tipo": "pergunta", "frente": "Qual o fecho para autoridades de hierarquia superior na comunicação oficial?", "verso": "\"Respeitosamente\".", "explicacao": "Para mesma hierarquia ou inferior: \"Atenciosamente\" (Manual de Redação da Presidência)."}, {"id": 2000003279, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que o Estatuto da Igualdade Racial entende por ações afirmativas?", "verso": "Programas e medidas especiais adotados pelo Estado e pela iniciativa privada para corrigir desigualdades raciais e promover a igualdade de oportunidades.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, VI."}, {"id": 2000003280, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que é o Sinapir?", "verso": "O Sistema Nacional de Promoção da Igualdade Racial, criado pelo Estatuto para organizar as políticas de igualdade racial.", "explicacao": "Lei 12.288/2010, art. 47."}, {"id": 2000003281, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O Estatuto da Igualdade Racial garante o livre exercício dos cultos de matriz africana?", "verso": "Sim. Garante a liberdade de consciência e de crença e o livre exercício dos cultos religiosos de matriz africana.", "explicacao": "Lei 12.288/2010, arts. 23 a 26."}, {"id": 2000003282, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que é a Lei 10.639/2003?", "verso": "A lei que tornou obrigatório o ensino de história e cultura afro-brasileira nas escolas.", "explicacao": "A Lei 11.645/2008 incluiu também a história e cultura indígena (LDB, art. 26-A)."}, {"id": 2000003283, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "Qual a pena do crime de racismo do art. 20 da Lei 7.716/1989?", "verso": "Reclusão de 1 a 3 anos e multa. Se cometido por meio de comunicação social ou redes sociais, reclusão de 2 a 5 anos.", "explicacao": "Lei 7.716/1989, art. 20, caput e § 2º."}, {"id": 2000003284, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "A Lei 14.532/2023 trouxe que agravamento para o racismo praticado em contexto de atividade esportiva ou artística?", "verso": "Pena de reclusão de 2 a 5 anos e proibição de frequentar locais destinados a práticas esportivas, artísticas ou culturais por 3 anos.", "explicacao": "Lei 7.716/1989, art. 20, § 2º-A."}, {"id": 2000003285, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "Praticar racismo no exercício de função pública aumenta a pena?", "verso": "Sim. A pena aumenta de 1/3 quando o crime é cometido por funcionário público no exercício das funções ou a pretexto de exercê-las.", "explicacao": "Lei 7.716/1989, art. 20-B, incluído pela Lei 14.532/2023."}, {"id": 2000003286, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é a Lei Mariana Ferrer (Lei 14.245/2021)?", "verso": "Lei que protege a vítima de crimes sexuais contra atos que atentem contra sua dignidade durante a audiência e o julgamento.", "explicacao": "Proíbe manifestações sobre fatos alheios ao processo e o uso de linguagem que ofenda a vítima ou testemunhas."}, {"id": 2000003287, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que a Lei 13.104/2015 fez em relação ao feminicídio?", "verso": "Criou a qualificadora do feminicídio e o incluiu no rol de crimes hediondos.", "explicacao": "Em 2024, a Lei 14.994 tornou o feminicídio um crime autônomo (art. 121-A do CP)."}, {"id": 2000003288, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é a misoginia?", "verso": "Ódio, aversão ou desprezo contra mulheres.", "explicacao": "Base de muitas formas de violência de gênero."}, {"id": 2000003289, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "O que a Convenção 169 da OIT garante aos povos indígenas e tribais?", "verso": "O direito à consulta prévia, livre e informada sobre medidas que os afetem diretamente.", "explicacao": "Promulgada no Brasil pelo Decreto 5.051/2004, hoje consolidado no Decreto 10.088/2019."}, {"id": 2000003290, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "O que a Constituição assegura aos indígenas sobre suas terras?", "verso": "Os direitos originários sobre as terras que tradicionalmente ocupam, cabendo à União demarcá-las e protegê-las.", "explicacao": "CF, art. 231."}, {"id": 2000003291, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "Quem é competente para processar e julgar a disputa sobre direitos indígenas?", "verso": "A Justiça Federal.", "explicacao": "CF, art. 109, XI."}, {"id": 2000003292, "trilha": "policial", "materia": "igual", "assunto": "Igualdade", "tipo": "pergunta", "frente": "O que é discriminação indireta?", "verso": "Medida aparentemente neutra que, na prática, prejudica de forma desproporcional um grupo.", "explicacao": "Ex.: exigência de requisito sem relação com o cargo que exclui um grupo."}, {"id": 2000003293, "trilha": "policial", "materia": "igual", "assunto": "Igualdade", "tipo": "pergunta", "frente": "O que é interseccionalidade?", "verso": "A análise de como diferentes formas de discriminação, como raça, gênero e classe, se combinam e se reforçam.", "explicacao": "Conceito usado nas políticas de igualdade."}, {"id": 2000003294, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Quem avalia a deficiência, quando necessário, segundo o Estatuto?", "verso": "Equipe multiprofissional e interdisciplinar, por avaliação biopsicossocial.", "explicacao": "Lei 13.146/2015, art. 2º, § 1º."}, {"id": 2000003295, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "A deficiência afeta o direito de casar, votar e ter filhos?", "verso": "Não. A deficiência não afeta a plena capacidade civil para esses atos.", "explicacao": "Lei 13.146/2015, art. 6º."}, {"id": 2000003296, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é a curatela da pessoa com deficiência, segundo o Estatuto?", "verso": "Medida protetiva extraordinária, proporcional às necessidades e pelo menor tempo possível, que afeta apenas atos de natureza patrimonial e negocial.", "explicacao": "Lei 13.146/2015, arts. 84 e 85."}, {"id": 2000003297, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é a acessibilidade, segundo o Estatuto?", "verso": "Possibilidade e condição de alcance para utilizar, com segurança e autonomia, espaços, transportes, informação e serviços.", "explicacao": "Lei 13.146/2015, art. 3º, I."}, {"id": 2000003298, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é tecnologia assistiva?", "verso": "Produtos, equipamentos, metodologias e serviços que promovem a funcionalidade e a autonomia da pessoa com deficiência.", "explicacao": "Lei 13.146/2015, art. 3º, III."}, {"id": 2000003299, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é a Libras?", "verso": "A Língua Brasileira de Sinais, reconhecida como meio legal de comunicação e expressão.", "explicacao": "Lei 10.436/2002."}, {"id": 2000003300, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual o percentual mínimo de vagas em estacionamentos para veículos que transportem pessoas com deficiência?", "verso": "2% das vagas, garantida pelo menos uma.", "explicacao": "Lei 13.146/2015, art. 47, § 1º."}, {"id": 2000003301, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "A pessoa com deficiência tem atendimento prioritário em delegacias e serviços públicos?", "verso": "Sim. O Estatuto garante atendimento prioritário em todas as instituições e serviços de atendimento ao público.", "explicacao": "Lei 13.146/2015, art. 9º, II."}, {"id": 2000003302, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual a pena do crime de discriminar pessoa em razão da deficiência?", "verso": "Reclusão de 1 a 3 anos e multa, aumentada de 1/3 se a vítima estiver sob cuidado do agente.", "explicacao": "Lei 13.146/2015, art. 88."}, {"id": 2000003303, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Apropriar-se de bens ou benefícios da pessoa com deficiência é crime?", "verso": "Sim. Reter ou desviar bens, proventos ou qualquer rendimento da pessoa com deficiência é crime.", "explicacao": "Lei 13.146/2015, art. 89."}, {"id": 2000003304, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual a reserva de vagas para pessoas com deficiência em empresas com 100 ou mais empregados?", "verso": "De 2% a 5% dos cargos, conforme o número de empregados.", "explicacao": "Lei 8.213/1991, art. 93 (lei de cotas)."}, {"id": 2000003305, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Pessoa com transtorno do espectro autista é considerada pessoa com deficiência?", "verso": "Sim, para todos os efeitos legais.", "explicacao": "Lei 12.764/2012, art. 1º, § 2º."}, {"id": 2000003306, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é o cão-guia, e onde ele pode entrar?", "verso": "Cão treinado para guiar pessoa com deficiência visual, que pode ingressar e permanecer com ela em qualquer ambiente público ou privado de uso coletivo.", "explicacao": "Lei 11.126/2005."}, {"id": 2000003307, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que são as barreiras atitudinais?", "verso": "Atitudes ou comportamentos que impedem ou prejudicam a participação social da pessoa com deficiência em igualdade de condições.", "explicacao": "Lei 13.146/2015, art. 3º, IV, e."}, {"id": 2000003308, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é a pessoa com mobilidade reduzida?", "verso": "Quem tem dificuldade de movimentação, permanente ou temporária, como idosos, gestantes, lactantes e pessoas com criança de colo.", "explicacao": "Lei 13.146/2015, art. 3º, IX."}, {"id": 2000003309, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pares", "frente": "Qual a diferença entre IA fraca (estreita) e IA forte (geral)?", "verso": "IA fraca: resolve tarefas específicas (reconhecer rostos, traduzir). IA forte: teria inteligência geral semelhante à humana, e ainda é hipotética.", "explicacao": "Os sistemas atuais são de IA estreita."}, {"id": 2000003310, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é aprendizado supervisionado?", "verso": "Treinar o modelo com exemplos já rotulados, com a resposta certa.", "explicacao": "Ex.: fotos marcadas como \"arma\" ou \"não arma\"."}, {"id": 2000003311, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é aprendizado por reforço?", "verso": "O modelo aprende por tentativa e erro, recebendo recompensas ou penalidades pelas ações.", "explicacao": "Usado em jogos e robótica."}, {"id": 2000003312, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é uma rede neural artificial?", "verso": "Modelo computacional inspirado no cérebro, formado por camadas de \"neurônios\" que ajustam pesos para aprender padrões.", "explicacao": "Base do aprendizado profundo (deep learning)."}, {"id": 2000003313, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é visão computacional?", "verso": "Área da IA que permite às máquinas interpretar imagens e vídeos.", "explicacao": "Ex.: leitura de placas de veículos e reconhecimento facial."}, {"id": 2000003314, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é processamento de linguagem natural (PLN)?", "verso": "Área da IA que permite às máquinas entender e produzir linguagem humana.", "explicacao": "Ex.: tradutores, chatbots e transcrição de áudio."}, {"id": 2000003315, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é um prompt?", "verso": "A instrução ou pergunta que o usuário dá a um sistema de IA generativa.", "explicacao": "Prompts claros e com contexto geram respostas melhores."}, {"id": 2000003316, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "Qual o principal risco do reconhecimento facial na segurança pública?", "verso": "Erros de identificação, maiores em alguns grupos, que podem levar a abordagens e prisões injustas.", "explicacao": "Por isso a identificação deve ser confirmada por outros meios."}, {"id": 2000003317, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é o \"humano no circuito\" (human in the loop)?", "verso": "Exigência de que uma pessoa revise e decida sobre o resultado da IA, especialmente em decisões que afetam direitos.", "explicacao": "Boa prática em segurança pública e justiça."}, {"id": 2000003318, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é a \"caixa-preta\" em IA?", "verso": "Quando não se consegue explicar como o modelo chegou a uma decisão.", "explicacao": "Por isso se valoriza a IA explicável."}, {"id": 2000003319, "trilha": "policial", "materia": "ia", "assunto": "Proteção de dados", "tipo": "pergunta", "frente": "Quais são as bases para o tratamento de dados pessoais pela segurança pública na LGPD?", "verso": "A LGPD não se aplica ao tratamento feito exclusivamente para segurança pública, defesa nacional, segurança do Estado ou investigação e repressão de infrações penais, que deve ter lei específica.", "explicacao": "LGPD (Lei 13.709/2018), art. 4º, III, e § 1º."}, {"id": 2000003320, "trilha": "policial", "materia": "ia", "assunto": "Proteção de dados", "tipo": "pergunta", "frente": "O que é anonimização de dados?", "verso": "Uso de meios técnicos para que o dado perca a possibilidade de associação a uma pessoa.", "explicacao": "Dado anonimizado, em regra, não é dado pessoal (LGPD, arts. 5º, XI, e 12)."}, {"id": 2000003321, "trilha": "policial", "materia": "ia", "assunto": "Inovação", "tipo": "pergunta", "frente": "O que é a Internet das Coisas (IoT)?", "verso": "Objetos do dia a dia conectados à internet, trocando dados, como câmeras, sensores e rastreadores.", "explicacao": "Muito usada em monitoramento urbano."}, {"id": 2000003322, "trilha": "policial", "materia": "ia", "assunto": "Inovação", "tipo": "pergunta", "frente": "O que é big data?", "verso": "Conjuntos de dados muito grandes e variados, gerados em alta velocidade, analisados com ferramentas especiais.", "explicacao": "Os 3 Vs: volume, velocidade e variedade."}, {"id": 2000003323, "trilha": "policial", "materia": "ia", "assunto": "Aplicações", "tipo": "pergunta", "frente": "O que é policiamento preditivo?", "verso": "Uso de dados e algoritmos para prever locais e horários com maior probabilidade de crimes.", "explicacao": "Exige cuidado com vieses dos dados históricos."}, {"id": 2000003324, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "De onde vem o conceito mais conhecido de desenvolvimento sustentável?", "verso": "Do Relatório Brundtland (\"Nosso Futuro Comum\"), de 1987.", "explicacao": "Atender às necessidades do presente sem comprometer as das gerações futuras."}, {"id": 2000003325, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é economia circular?", "verso": "Modelo que mantém produtos e materiais em uso pelo maior tempo possível, por reutilização, reparo e reciclagem.", "explicacao": "Opõe-se ao modelo linear de extrair, produzir e descartar."}, {"id": 2000003326, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é pegada de carbono?", "verso": "A quantidade de gases de efeito estufa emitida, direta ou indiretamente, por uma pessoa, empresa ou produto.", "explicacao": "Medida em toneladas de CO₂ equivalente."}, {"id": 2000003327, "trilha": "policial", "materia": "sust", "assunto": "Clima", "tipo": "pergunta", "frente": "O que é o efeito estufa?", "verso": "Fenômeno natural em que gases da atmosfera retêm parte do calor do Sol. O excesso desses gases causa o aquecimento global.", "explicacao": "Principais gases: CO₂, metano e óxido nitroso."}, {"id": 2000003328, "trilha": "policial", "materia": "sust", "assunto": "Clima", "tipo": "pergunta", "frente": "O que foi a Rio-92 (Eco-92)?", "verso": "A Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento, realizada no Rio de Janeiro em 1992.", "explicacao": "Dela saíram a Agenda 21 e as convenções sobre clima e biodiversidade."}, {"id": 2000003329, "trilha": "policial", "materia": "sust", "assunto": "Clima", "tipo": "pergunta", "frente": "Qual a cidade brasileira que sediou a COP30, em 2025?", "verso": "Belém, no Pará.", "explicacao": "Conferência da ONU sobre Mudança do Clima."}, {"id": 2000003330, "trilha": "policial", "materia": "sust", "assunto": "Resíduos", "tipo": "pergunta", "frente": "Qual a ordem de prioridade na gestão de resíduos sólidos?", "verso": "Não geração, redução, reutilização, reciclagem, tratamento e disposição final ambientalmente adequada dos rejeitos.", "explicacao": "Política Nacional de Resíduos Sólidos (Lei 12.305/2010), art. 9º."}, {"id": 2000003331, "trilha": "policial", "materia": "sust", "assunto": "Resíduos", "tipo": "pergunta", "frente": "O que é a responsabilidade compartilhada pelo ciclo de vida dos produtos?", "verso": "O conjunto de obrigações de fabricantes, importadores, distribuidores, comerciantes, consumidores e poder público para reduzir resíduos e seus impactos.", "explicacao": "Lei 12.305/2010, arts. 3º, XVII, e 30."}, {"id": 2000003332, "trilha": "policial", "materia": "sust", "assunto": "Gestão pública", "tipo": "pergunta", "frente": "O que são compras públicas sustentáveis?", "verso": "Contratações que consideram critérios ambientais, sociais e econômicos, como eficiência energética e menor geração de resíduos.", "explicacao": "A Lei 14.133/2021 prevê o desenvolvimento nacional sustentável como objetivo da licitação (art. 11, IV)."}, {"id": 2000003333, "trilha": "policial", "materia": "sust", "assunto": "Constituição", "tipo": "pergunta", "frente": "A Constituição exige estudo de impacto ambiental para quê?", "verso": "Para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, com publicidade.", "explicacao": "CF, art. 225, § 1º, IV."}, {"id": 2000003334, "trilha": "policial", "materia": "sust", "assunto": "Constituição", "tipo": "pergunta", "frente": "As condutas lesivas ao meio ambiente geram que tipo de responsabilidade?", "verso": "Sanções penais e administrativas, independentemente da obrigação de reparar os danos, para pessoas físicas ou jurídicas.", "explicacao": "CF, art. 225, § 3º."}, {"id": 2000003335, "trilha": "policial", "materia": "sust", "assunto": "Agenda 2030", "tipo": "pergunta", "frente": "Qual o ODS 16 da Agenda 2030?", "verso": "Paz, justiça e instituições eficazes.", "explicacao": "É o ODS mais ligado à segurança pública e ao combate à violência."}, {"id": 2000003336, "trilha": "policial", "materia": "leg", "assunto": "Violência contra criança", "tipo": "pergunta", "frente": "O que é a Lei Henry Borel (Lei 14.344/2022)?", "verso": "Lei que cria mecanismos para prevenir e enfrentar a violência doméstica e familiar contra a criança e o adolescente, com medidas protetivas de urgência.", "explicacao": "Inspirada na Lei Maria da Penha."}, {"id": 2000003337, "trilha": "policial", "materia": "leg", "assunto": "Violência contra criança", "tipo": "pergunta", "frente": "A Lei Henry Borel tornou hediondo qual crime?", "verso": "O homicídio contra menor de 14 anos.", "explicacao": "Lei 14.344/2022, que alterou o CP e a Lei 8.072/1990."}, {"id": 2000003338, "trilha": "policial", "materia": "leg", "assunto": "Violência contra criança", "tipo": "pergunta", "frente": "Na Lei Henry Borel, o delegado pode afastar o agressor do lar?", "verso": "Sim, quando o município não for sede de comarca, havendo risco atual ou iminente à vida ou à integridade da criança ou do adolescente, comunicando o juiz em 24 horas.", "explicacao": "Lei 14.344/2022, art. 14. Na falta de delegado, o policial pode fazê-lo."}, {"id": 2000003339, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Em que prazo o juiz deve decidir sobre as medidas protetivas pedidas pela vítima?", "verso": "Em 48 horas.", "explicacao": "Lei 11.340/2006, art. 18."}, {"id": 2000003340, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "As medidas protetivas da Lei Maria da Penha dependem da tipificação penal da violência?", "verso": "Não. Independem da tipificação penal, de ação penal, de inquérito ou de boletim de ocorrência.", "explicacao": "Lei 11.340/2006, art. 19, § 5º, incluído pela Lei 14.550/2023."}, {"id": 2000003341, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Quais providências a autoridade policial deve adotar ao atender a mulher em situação de violência?", "verso": "Garantir proteção policial, encaminhá-la ao hospital e ao IML, fornecer transporte para abrigo, acompanhá-la para retirar seus pertences e informá-la de seus direitos.", "explicacao": "Lei 11.340/2006, art. 11."}, {"id": 2000003342, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "O agressor pode ter a posse de arma suspensa por medida protetiva?", "verso": "Sim. A suspensão da posse ou restrição do porte de armas é medida protetiva que obriga o agressor.", "explicacao": "Lei 11.340/2006, art. 22, I."}, {"id": 2000003343, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "O que é a Lei 14.188/2021 (Sinal Vermelho)?", "verso": "Lei que criou o programa Sinal Vermelho contra a Violência Doméstica (um X vermelho na mão como pedido de socorro) e o crime de violência psicológica contra a mulher.", "explicacao": "Incluiu o art. 147-B no CP."}, {"id": 2000003344, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a pena do porte ilegal de arma de fogo de uso permitido?", "verso": "Reclusão de 2 a 4 anos e multa.", "explicacao": "Lei 10.826/2003, art. 14."}, {"id": 2000003345, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "O porte de munição isolada, sem a arma, é crime?", "verso": "Sim. O tipo inclui munição e acessório.", "explicacao": "Lei 10.826/2003, arts. 12 e 14. O STF admite insignificância em casos excepcionais de pequena quantidade sem arma."}, {"id": 2000003346, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "O responsável por empresa de segurança ou de transporte de valores que não comunica, em 24 horas, a perda, o furto ou o roubo de arma sob sua guarda comete crime?", "verso": "Sim. Responde nas mesmas penas da omissão de cautela: deve registrar ocorrência policial e comunicar à Polícia Federal nas primeiras 24 horas.", "explicacao": "Lei 10.826/2003, art. 13, parágrafo único."}, {"id": 2000003347, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Quem expede o porte de arma de fogo de uso permitido para civis?", "verso": "A Polícia Federal, após autorização do SINARM, com prazo e eficácia definidos.", "explicacao": "Lei 10.826/2003, art. 10."}, {"id": 2000003348, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Até que idade o ECA pode ser aplicado excepcionalmente?", "verso": "Até os 21 anos, nos casos previstos em lei, como a internação.", "explicacao": "ECA, art. 2º, parágrafo único."}, {"id": 2000003349, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Qual a idade para a liberação compulsória do internado?", "verso": "21 anos.", "explicacao": "ECA, art. 121, § 5º."}, {"id": 2000003350, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "De quanto em quanto tempo a internação do adolescente deve ser reavaliada?", "verso": "No máximo a cada 6 meses, por decisão fundamentada.", "explicacao": "ECA, art. 121, § 2º."}, {"id": 2000003351, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Quais as hipóteses de internação do adolescente?", "verso": "Ato infracional com grave ameaça ou violência à pessoa, reiteração no cometimento de outras infrações graves ou descumprimento reiterado e injustificável de medida anterior.", "explicacao": "ECA, art. 122. No descumprimento, a internação é de até 3 meses."}, {"id": 2000003352, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "A apreensão do adolescente é permitida em que situações?", "verso": "Só em flagrante de ato infracional ou por ordem escrita e fundamentada do juiz.", "explicacao": "ECA, art. 106."}, {"id": 2000003353, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Quem deve ser comunicado imediatamente da apreensão do adolescente?", "verso": "O juiz e a família do apreendido ou a pessoa por ele indicada.", "explicacao": "ECA, art. 107."}, {"id": 2000003354, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "O que é o crime de corrupção de menores do ECA?", "verso": "Corromper ou facilitar a corrupção de menor de 18 anos, praticando com ele infração penal ou induzindo-o a praticá-la.", "explicacao": "ECA, art. 244-B. É crime formal (Súmula 500 do STJ)."}, {"id": 2000003355, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Armazenar fotografia ou vídeo com cena de sexo explícito envolvendo criança ou adolescente é crime?", "verso": "Sim. Adquirir, possuir ou armazenar esse material é crime.", "explicacao": "ECA, art. 241-B."}, {"id": 2000003356, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Aliciar criança, por meio de comunicação, para praticar ato libidinoso é crime?", "verso": "Sim. Aliciar, assediar, instigar ou constranger criança com esse fim é crime.", "explicacao": "ECA, art. 241-D."}, {"id": 2000003357, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Deixar de prestar assistência à pessoa idosa em situação de iminente perigo, quando possível fazê-lo sem risco, é crime?", "verso": "Sim, previsto no Estatuto da Pessoa Idosa.", "explicacao": "Lei 10.741/2003, art. 97."}, {"id": 2000003358, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Apropriar-se de bens, proventos ou pensão da pessoa idosa é crime?", "verso": "Sim. Desviar ou dar aplicação diversa da finalidade aos bens, proventos ou rendimentos da pessoa idosa.", "explicacao": "Lei 10.741/2003, art. 102."}, {"id": 2000003359, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Qual a prioridade especial do Estatuto?", "verso": "Pessoas maiores de 80 anos têm prioridade especial sobre os demais idosos.", "explicacao": "Lei 10.741/2003, art. 3º, § 2º."}, {"id": 2000003360, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Quais provas podem demonstrar a embriaguez ao volante?", "verso": "Teste de alcoolemia, exame clínico, perícia, vídeo, prova testemunhal ou outros meios de prova em direito admitidos.", "explicacao": "CTB, art. 306, § 2º."}, {"id": 2000003361, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Qual o efeito da recusa ao bafômetro?", "verso": "Infração administrativa gravíssima, com multa e suspensão do direito de dirigir. Não é crime.", "explicacao": "CTB, art. 165-A. Ninguém é obrigado a produzir prova contra si."}, {"id": 2000003362, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "O que é o crime do art. 311 do CTB?", "verso": "Trafegar em velocidade incompatível com a segurança perto de escolas, hospitais, estações de embarque ou onde haja grande movimentação de pessoas, gerando perigo de dano.", "explicacao": "CTB, art. 311."}, {"id": 2000003363, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "Quais setores são obrigados a comunicar operações suspeitas ao Coaf?", "verso": "Bancos, corretoras, joalherias, imobiliárias, cartórios, comerciantes de bens de luxo, entre outros listados na lei.", "explicacao": "Lei 9.613/1998, arts. 9º a 11."}, {"id": 2000003364, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "Qual a pena do crime de lavagem de dinheiro?", "verso": "Reclusão de 3 a 10 anos e multa.", "explicacao": "Lei 9.613/1998, art. 1º."}, {"id": 2000003365, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "O processo por lavagem depende de condenação pelo crime antecedente?", "verso": "Não. Basta haver indícios suficientes da infração antecedente.", "explicacao": "Lei 9.613/1998, art. 2º, II, e § 1º."}, {"id": 2000003366, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "pergunta", "frente": "Quais motivações caracterizam o terrorismo na Lei 13.260/2016?", "verso": "Xenofobia, discriminação ou preconceito de raça, cor, etnia e religião, com o fim de provocar terror social ou generalizado.", "explicacao": "Lei 13.260/2016, art. 2º."}, {"id": 2000003367, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "pergunta", "frente": "Qual a pena do crime de terrorismo?", "verso": "Reclusão de 12 a 30 anos, além das penas pela ameaça ou violência.", "explicacao": "Lei 13.260/2016, art. 2º, § 1º."}, {"id": 2000003368, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "pergunta", "frente": "Quem julga os crimes de terrorismo?", "verso": "A Justiça Federal, e a investigação cabe à Polícia Federal.", "explicacao": "Lei 13.260/2016, art. 11."}, {"id": 2000003369, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "Quais penas podem ser aplicadas à pessoa jurídica por crime ambiental?", "verso": "Multa, restritivas de direitos (suspensão de atividades, interdição, proibição de contratar com o poder público) e prestação de serviços à comunidade.", "explicacao": "Lei 9.605/1998, art. 21."}, {"id": 2000003370, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "A responsabilidade penal da pessoa jurídica exclui a das pessoas físicas no crime ambiental?", "verso": "Não. A pessoa jurídica responde sem prejuízo da responsabilidade das pessoas físicas autoras, coautoras ou partícipes.", "explicacao": "Lei 9.605/1998, art. 3º, parágrafo único."}, {"id": 2000003371, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "Matar animal silvestre sem permissão é crime?", "verso": "Sim. Matar, perseguir, caçar, apanhar ou utilizar espécimes da fauna silvestre sem autorização é crime.", "explicacao": "Lei 9.605/1998, art. 29."}, {"id": 2000003372, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Decretar a condução coercitiva de testemunha ou investigado sem prévia intimação é abuso de autoridade?", "verso": "Sim, quando manifestamente descabida ou sem intimação prévia de comparecimento ao juízo.", "explicacao": "Lei 13.869/2019, art. 10."}, {"id": 2000003373, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Deixar de comunicar a prisão ao juiz no prazo legal é abuso de autoridade?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 12."}, {"id": 2000003374, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Divulgar gravação sem relação com a prova, expondo a intimidade do investigado, é abuso?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 28."}, {"id": 2000003375, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Iniciar investigação sem justa causa fundamentada contra pessoa sabidamente inocente é abuso?", "verso": "Sim. Requisitar ou instaurar procedimento investigatório à falta de qualquer indício da prática de crime.", "explicacao": "Lei 13.869/2019, arts. 27 e 30."}, {"id": 2000003376, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual percentual de pena o condenado primário deve cumprir para progredir de regime em crime sem violência ou grave ameaça?", "verso": "16%.", "explicacao": "LEP, art. 112, I."}, {"id": 2000003377, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual o percentual de progressão para o condenado reincidente em crime sem violência ou grave ameaça?", "verso": "20%.", "explicacao": "LEP, art. 112, II."}, {"id": 2000003378, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual o percentual de progressão para o reincidente em crime hediondo ou equiparado?", "verso": "60%.", "explicacao": "LEP, art. 112, VII."}, {"id": 2000003379, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Quanto tempo de estudo gera um dia de remição?", "verso": "12 horas de frequência escolar, divididas em no mínimo 3 dias.", "explicacao": "LEP, art. 126, § 1º, I. Para o trabalho, 1 dia a cada 3 trabalhados."}, {"id": 2000003380, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "O preso tem direito a visita do cônjuge, da companheira, de parentes e amigos?", "verso": "Sim, em dias determinados.", "explicacao": "LEP, art. 41, X. O direito pode ser suspenso ou restringido por ato motivado do diretor."}, {"id": 2000003381, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "A posse ou o porte ilegal de arma de fogo de uso proibido é hediondo?", "verso": "Sim.", "explicacao": "Lei 8.072/1990, art. 1º, parágrafo único, II."}, {"id": 2000003382, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "O furto qualificado pelo uso de explosivo é hediondo?", "verso": "Sim.", "explicacao": "Lei 8.072/1990, art. 1º, IX, incluído pela Lei 13.964/2019."}, {"id": 2000003383, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Quando a pena da organização criminosa é aumentada se houver emprego de arma de fogo?", "verso": "Até a metade.", "explicacao": "Lei 12.850/2013, art. 2º, § 2º."}, {"id": 2000003384, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "Qual a pena da contravenção de vias de fato?", "verso": "Prisão simples de 15 dias a 3 meses, ou multa, se o fato não constituir crime.", "explicacao": "Decreto-Lei 3.688/1941, art. 21. Aumenta de 1/3 até a metade se a vítima tem mais de 60 anos."}, {"id": 2000003385, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "Qual a contravenção de quem perturba o trabalho ou o sossego alheio com gritaria ou algazarra?", "verso": "Perturbação do trabalho ou do sossego alheios.", "explicacao": "Decreto-Lei 3.688/1941, art. 42."}, {"id": 2000003386, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição permite a entrada em casa para cumprir ordem judicial à noite?", "verso": "Não. A ordem judicial só autoriza a entrada durante o dia. À noite, só em flagrante, desastre ou para prestar socorro.", "explicacao": "CF, art. 5º, XI."}, {"id": 2000003387, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O que a Constituição garante sobre a herança e a função social da propriedade?", "verso": "Garante o direito de herança e a propriedade, que deve atender à sua função social.", "explicacao": "CF, art. 5º, XXII, XXIII e XXX."}, {"id": 2000003388, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição permite a prisão civil do depositário infiel?", "verso": "O texto prevê, mas o STF considera ilícita qualquer prisão civil de depositário infiel.", "explicacao": "CF, art. 5º, LXVII, e Súmula Vinculante 25."}, {"id": 2000003389, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição garante assistência ao preso pela família e por advogado?", "verso": "Sim. O preso será informado de seus direitos, entre os quais o de permanecer calado, assegurada a assistência da família e de advogado.", "explicacao": "CF, art. 5º, LXIII."}, {"id": 2000003390, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O preso tem direito de saber quem o prendeu?", "verso": "Sim. Tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial.", "explicacao": "CF, art. 5º, LXIV."}, {"id": 2000003391, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição exige lei para criar crime e pena?", "verso": "Sim. Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.", "explicacao": "CF, art. 5º, XXXIX."}, {"id": 2000003392, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A lei penal pode retroagir?", "verso": "Só para beneficiar o réu.", "explicacao": "CF, art. 5º, XL."}, {"id": 2000003393, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quem será punido pela lei, segundo a Constituição, nos crimes de tortura, tráfico, terrorismo e hediondos?", "verso": "Os mandantes, os executores e os que, podendo evitá-los, se omitirem.", "explicacao": "CF, art. 5º, XLIII."}, {"id": 2000003394, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição garante sigilo da fonte ao jornalista?", "verso": "Sim. É resguardado o sigilo da fonte, quando necessário ao exercício profissional.", "explicacao": "CF, art. 5º, XIV."}, {"id": 2000003395, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O que a Constituição diz sobre provas obtidas por meios ilícitos?", "verso": "São inadmissíveis no processo.", "explicacao": "CF, art. 5º, LVI."}, {"id": 2000003396, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pergunta", "frente": "Quem pode impetrar mandado de segurança coletivo?", "verso": "Partido político com representação no Congresso, organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos 1 ano.", "explicacao": "CF, art. 5º, LXX."}, {"id": 2000003397, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual emenda constitucional criou as polícias penais?", "verso": "A EC 104/2019.", "explicacao": "CF, art. 144, VI, e § 5º-A."}, {"id": 2000003398, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "A Polícia Federal exerce com exclusividade as funções de polícia judiciária da União?", "verso": "Sim.", "explicacao": "CF, art. 144, § 1º, IV."}, {"id": 2000003399, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Cabe à Polícia Federal prevenir e reprimir o tráfico de drogas?", "verso": "Sim, o tráfico ilícito de entorpecentes, o contrabando e o descaminho, sem prejuízo da ação de outros órgãos.", "explicacao": "CF, art. 144, § 1º, II."}, {"id": 2000003400, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Como é feita a remuneração dos servidores policiais do art. 144?", "verso": "Na forma de subsídio, em parcela única.", "explicacao": "CF, art. 144, § 9º, e art. 39, § 4º."}, {"id": 2000003401, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que o STF decidiu sobre as guardas municipais na ADPF 995?", "verso": "Que as guardas municipais integram o Sistema de Segurança Pública.", "explicacao": "Julgamento de 2023. Elas não exercem polícia judiciária."}, {"id": 2000003402, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais os requisitos para criar uma CPI?", "verso": "Requerimento de 1/3 dos membros da Casa, fato determinado e prazo certo.", "explicacao": "CF, art. 58, § 3º."}, {"id": 2000003403, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "A CPI pode decretar prisão, salvo em flagrante?", "verso": "Não. Também não pode decretar busca domiciliar nem interceptação telefônica, que dependem de ordem judicial.", "explicacao": "Jurisprudência do STF (cláusula de reserva de jurisdição)."}, {"id": 2000003404, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Desde quando os deputados e senadores não podem ser presos, salvo em flagrante de crime inafiançável?", "verso": "Desde a expedição do diploma.", "explicacao": "CF, art. 53, § 2º."}, {"id": 2000003405, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quantos deputados federais cada estado pode ter?", "verso": "No mínimo 8 e no máximo 70.", "explicacao": "CF, art. 45, § 1º."}, {"id": 2000003406, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Quem substitui o Presidente nos impedimentos e sucede em caso de vaga?", "verso": "O Vice-Presidente. Depois, na ordem, o Presidente da Câmara, o do Senado e o do STF.", "explicacao": "CF, arts. 79 e 80."}, {"id": 2000003407, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Qual a idade mínima para Governador?", "verso": "30 anos.", "explicacao": "CF, art. 14, § 3º, VI, b. Deputado e Prefeito: 21; Vereador: 18."}, {"id": 2000003408, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Qual a idade para ser nomeado ministro do STF?", "verso": "Mais de 35 e menos de 70 anos, com notável saber jurídico e reputação ilibada.", "explicacao": "CF, art. 101, com redação da EC 122/2022."}, {"id": 2000003409, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quem nomeia os ministros do STF?", "verso": "O Presidente da República, depois de aprovada a escolha pela maioria absoluta do Senado.", "explicacao": "CF, art. 101, parágrafo único."}, {"id": 2000003410, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "Quem chefia o Ministério Público da União?", "verso": "O Procurador-Geral da República, nomeado pelo Presidente entre integrantes da carreira, maiores de 35 anos, após aprovação do Senado, para mandato de 2 anos, permitida a recondução.", "explicacao": "CF, art. 128, § 1º."}, {"id": 2000003411, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "O Ministério Público pode exercer a advocacia?", "verso": "Não. É vedado aos membros do MP exercer a advocacia.", "explicacao": "CF, art. 128, § 5º, II, b."}, {"id": 2000003412, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pergunta", "frente": "Quais as hipóteses de estado de defesa?", "verso": "Preservar ou restabelecer a ordem pública ou a paz social ameaçadas por grave e iminente instabilidade institucional ou atingidas por calamidades de grandes proporções na natureza.", "explicacao": "CF, art. 136."}, {"id": 2000003413, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pergunta", "frente": "No estado de defesa, a prisão por crime contra o Estado pode durar quanto tempo sem autorização judicial?", "verso": "Não pode ser superior a 10 dias, salvo autorização do Poder Judiciário.", "explicacao": "CF, art. 136, § 3º, III."}, {"id": 2000003414, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Quais os casos de intervenção federal nos estados?", "verso": "Manter a integridade nacional, repelir invasão, pôr termo a grave comprometimento da ordem pública, garantir o livre exercício dos Poderes, reorganizar finanças, prover a execução de lei ou ordem judicial e assegurar princípios constitucionais sensíveis.", "explicacao": "CF, art. 34."}, {"id": 2000003415, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "A quem compete organizar e manter a polícia civil e militar do Distrito Federal?", "verso": "À União.", "explicacao": "CF, art. 21, XIV."}, {"id": 2000003416, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Até quando o servidor pode acumular cargos públicos?", "verso": "Só nos casos permitidos (dois de professor; um de professor com outro técnico ou científico; dois privativos de profissionais de saúde) e com compatibilidade de horários.", "explicacao": "CF, art. 37, XVI."}, {"id": 2000003417, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual o prazo de prescrição dos ilícitos que causem prejuízo ao erário?", "verso": "A lei estabelece os prazos, ressalvadas as ações de ressarcimento.", "explicacao": "CF, art. 37, § 5º. O STF entende que só é imprescritível o ressarcimento por ato doloso de improbidade."}, {"id": 2000003418, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pergunta", "frente": "O que é o critério jus soli e o jus sanguinis?", "verso": "Jus soli: nacionalidade pelo local de nascimento. Jus sanguinis: pela nacionalidade dos pais.", "explicacao": "O Brasil adota o jus soli como regra, com hipóteses de jus sanguinis (CF, art. 12, I)."}, {"id": 2000003419, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "O que é a inelegibilidade reflexa?", "verso": "São inelegíveis, no território de jurisdição do titular, o cônjuge e os parentes até o 2º grau do Presidente, Governador ou Prefeito, salvo se já titulares de mandato e candidatos à reeleição.", "explicacao": "CF, art. 14, § 7º."}, {"id": 2000003420, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "O que é a ação de impugnação de mandato eletivo?", "verso": "Ação para impugnar o mandato perante a Justiça Eleitoral em até 15 dias após a diplomação, com provas de abuso de poder econômico, corrupção ou fraude.", "explicacao": "CF, art. 14, §§ 10 e 11."}, {"id": 2000003421, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que é a presunção de legitimidade do ato administrativo?", "verso": "O ato é considerado verdadeiro e conforme a lei até prova em contrário.", "explicacao": "Presunção relativa: inverte o ônus da prova para quem a contesta."}, {"id": 2000003422, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que é a imperatividade do ato administrativo?", "verso": "O poder de impor obrigações a terceiros, independentemente de sua concordância.", "explicacao": "Nem todo ato tem imperatividade (ex.: atos enunciativos)."}, {"id": 2000003423, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que é o ato administrativo complexo?", "verso": "Ato formado pela manifestação de vontade de dois ou mais órgãos, que se fundem em um só ato.", "explicacao": "Ex.: nomeação que depende de aprovação de outro órgão."}, {"id": 2000003424, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Qual a diferença entre ato complexo e ato composto?", "verso": "Complexo: vontades de órgãos diferentes formam um único ato. Composto: um ato principal depende de outro acessório (aprovação, visto) para produzir efeitos.", "explicacao": "Classificação doutrinária."}, {"id": 2000003425, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que é o vício de competência no ato administrativo?", "verso": "Quando o ato é praticado por agente sem atribuição legal. Pode ser convalidado se a competência não for exclusiva.", "explicacao": "Lei 9.784/1999, art. 55."}, {"id": 2000003426, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "O que é uma fundação pública?", "verso": "Entidade da Administração indireta, com patrimônio destinado a uma finalidade de interesse social, criada ou autorizada por lei.", "explicacao": "CF, art. 37, XIX."}, {"id": 2000003427, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "O que é o consórcio público?", "verso": "Associação entre entes federados para gestão associada de serviços públicos, com personalidade de direito público ou privado.", "explicacao": "Lei 11.107/2005."}, {"id": 2000003428, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "O que é uma organização social (OS)?", "verso": "Entidade privada sem fins lucrativos que recebe essa qualificação do poder público e firma contrato de gestão para atuar em áreas como saúde e educação.", "explicacao": "Lei 9.637/1998. Integra o terceiro setor, não a Administração."}, {"id": 2000003429, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pares", "frente": "Qual a diferença entre órgão e entidade?", "verso": "Órgão: unidade sem personalidade jurídica (ex.: ministério). Entidade: unidade com personalidade jurídica própria (ex.: autarquia).", "explicacao": "Lei 9.784/1999, art. 1º, § 2º."}, {"id": 2000003430, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O poder de polícia pode ser delegado a empresa estatal?", "verso": "Segundo o STF, as fases de consentimento, fiscalização e sanção podem ser delegadas a pessoa jurídica de direito privado da Administração indireta, de capital majoritariamente público, que preste exclusivamente serviço público próprio do Estado em regime não concorrencial. A fase de ordem (legislar) não pode.", "explicacao": "STF, RE 633.782 (Tema 532)."}, {"id": 2000003431, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que é o abuso de poder por omissão?", "verso": "Quando a autoridade deixa de praticar ato que estava obrigada a praticar.", "explicacao": "O abuso de poder pode ser comissivo ou omissivo."}, {"id": 2000003432, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Qual o prazo para o servidor nomeado entrar em exercício após a posse, na Lei 8.112?", "verso": "15 dias.", "explicacao": "Lei 8.112/1990, art. 15, § 1º. A posse deve ocorrer em até 30 dias da nomeação."}, {"id": 2000003433, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "O que é a readaptação na Lei 8.112?", "verso": "Investidura do servidor em cargo de atribuições compatíveis com a limitação que sofreu em sua capacidade física ou mental.", "explicacao": "Lei 8.112/1990, art. 24."}, {"id": 2000003434, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "O que é o aproveitamento na Lei 8.112?", "verso": "O retorno do servidor em disponibilidade a cargo de atribuições e vencimentos compatíveis com o anteriormente ocupado.", "explicacao": "Lei 8.112/1990, art. 30."}, {"id": 2000003435, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Qual o prazo para o servidor pedir a reconsideração ou o recurso, na Lei 8.112?", "verso": "30 dias, a contar da publicação ou da ciência da decisão.", "explicacao": "Lei 8.112/1990, art. 108."}, {"id": 2000003436, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Qual penalidade se aplica a quem pratica abandono de cargo na Lei 8.112?", "verso": "Demissão.", "explicacao": "Lei 8.112/1990, arts. 132, II, e 138: ausência intencional por mais de 30 dias consecutivos."}, {"id": 2000003437, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "A suspensão pode ser convertida em multa?", "verso": "Sim. Quando houver conveniência para o serviço, a suspensão pode ser convertida em multa de 50% por dia, ficando o servidor obrigado a trabalhar.", "explicacao": "Lei 8.112/1990, art. 130, § 2º."}, {"id": 2000003438, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "O que é a revisão do processo disciplinar?", "verso": "Pode ser pedida a qualquer tempo, quando surgirem fatos novos ou circunstâncias que justifiquem a inocência ou a inadequação da pena. Não pode agravar a penalidade.", "explicacao": "Lei 8.112/1990, arts. 174 e 182."}, {"id": 2000003439, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Quais as fases da licitação na Lei 14.133/2021?", "verso": "Preparatória, divulgação do edital, apresentação de propostas e lances, julgamento, habilitação, recursal e homologação.", "explicacao": "Lei 14.133/2021, art. 17. A habilitação vem, em regra, depois do julgamento."}, {"id": 2000003440, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "O que é o diálogo competitivo?", "verso": "Modalidade para contratações de inovação tecnológica ou soluções complexas, em que a Administração dialoga com licitantes pré-selecionados para desenvolver alternativas.", "explicacao": "Lei 14.133/2021, art. 32."}, {"id": 2000003441, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Qual a modalidade de licitação para venda de bens inservíveis ou apreendidos?", "verso": "O leilão.", "explicacao": "Lei 14.133/2021, art. 6º, XL."}, {"id": 2000003442, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Qual a modalidade para escolha de trabalho técnico, científico ou artístico, com prêmio ao vencedor?", "verso": "O concurso.", "explicacao": "Lei 14.133/2021, art. 6º, XXXIX."}, {"id": 2000003443, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pergunta", "frente": "O Tribunal de Contas pode sustar diretamente um contrato?", "verso": "Não. A sustação do contrato é feita pelo Congresso Nacional. O TCU pode sustar atos, e só decide sobre o contrato se o Congresso e o Executivo não agirem em 90 dias.", "explicacao": "CF, art. 71, X e §§ 1º e 2º."}, {"id": 2000003444, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pergunta", "frente": "Qual a eficácia das decisões do Tribunal de Contas que imputam débito ou multa?", "verso": "Têm eficácia de título executivo.", "explicacao": "CF, art. 71, § 3º."}, {"id": 2000003445, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O que são as excludentes da responsabilidade civil do Estado?", "verso": "Culpa exclusiva da vítima, caso fortuito ou força maior e fato exclusivo de terceiro, que rompem o nexo causal.", "explicacao": "Teoria do risco administrativo. A culpa concorrente apenas reduz a indenização."}, {"id": 2000003446, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O Estado responde por danos causados por policial de folga usando a arma da corporação?", "verso": "Sim, segundo o STF, quando o agente se vale da condição de servidor ou de instrumento do Estado.", "explicacao": "Jurisprudência do STF sobre o art. 37, § 6º, da CF."}, {"id": 2000003447, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Quais as sanções do ato de improbidade que causa enriquecimento ilícito?", "verso": "Perda dos bens acrescidos, perda da função, suspensão dos direitos políticos até 14 anos, multa equivalente ao acréscimo e proibição de contratar com o poder público até 14 anos.", "explicacao": "Lei 8.429/1992, art. 12, I, com redação da Lei 14.230/2021."}, {"id": 2000003448, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Cabe acordo de não persecução civil na improbidade?", "verso": "Sim. O MP pode celebrá-lo, com ressarcimento integral do dano e reversão da vantagem indevida.", "explicacao": "Lei 8.429/1992, art. 17-B."}, {"id": 2000003449, "trilha": "policial", "materia": "adm", "assunto": "Acesso à informação", "tipo": "pergunta", "frente": "Qual o prazo para o órgão responder a um pedido de acesso à informação?", "verso": "Até 20 dias, prorrogáveis por mais 10, com justificativa.", "explicacao": "Lei 12.527/2011, art. 11, § 2º."}, {"id": 2000003450, "trilha": "policial", "materia": "adm", "assunto": "Acesso à informação", "tipo": "pergunta", "frente": "Quais os graus de sigilo da informação na Lei de Acesso à Informação?", "verso": "Ultrassecreta (25 anos), secreta (15 anos) e reservada (5 anos).", "explicacao": "Lei 12.527/2011, art. 24, § 1º."}, {"id": 2000003451, "trilha": "policial", "materia": "adm", "assunto": "Acesso à informação", "tipo": "pergunta", "frente": "Por quanto tempo as informações pessoais relativas à intimidade ficam com acesso restrito?", "verso": "Por até 100 anos, independentemente de classificação de sigilo.", "explicacao": "Lei 12.527/2011, art. 31, § 1º, I."}, {"id": 2000003452, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "O que é a reincidência?", "verso": "Quando o agente comete novo crime depois do trânsito em julgado de sentença que o condenou por crime anterior, no Brasil ou no exterior.", "explicacao": "CP, art. 63."}, {"id": 2000003453, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Cite atenuantes genéricas do art. 65 do CP.", "verso": "Ser menor de 21 anos na data do fato ou maior de 70 na sentença, desconhecimento da lei, motivo de relevante valor, procurar reparar o dano, coação resistível e confissão espontânea.", "explicacao": "CP, art. 65."}, {"id": 2000003454, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "O que é medida de segurança?", "verso": "Sanção aplicada ao inimputável (ou semi-imputável, se necessário) que pratica fato típico e ilícito, nas formas de internação ou tratamento ambulatorial.", "explicacao": "CP, arts. 96 e 97."}, {"id": 2000003455, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual o prazo máximo da medida de segurança, segundo o STJ?", "verso": "Não pode ultrapassar o limite máximo da pena abstratamente cominada ao delito praticado.", "explicacao": "Súmula 527 do STJ."}, {"id": 2000003456, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é o crime de exploração de prestígio?", "verso": "Solicitar ou receber vantagem a pretexto de influir em juiz, jurado, membro do MP, funcionário de justiça, perito, tradutor, intérprete ou testemunha.", "explicacao": "CP, art. 357."}, {"id": 2000003457, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é o tráfico de influência?", "verso": "Solicitar, exigir, cobrar ou obter vantagem a pretexto de influir em ato praticado por funcionário público no exercício da função.", "explicacao": "CP, art. 332."}, {"id": 2000003458, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é o crime de fraude processual?", "verso": "Inovar artificiosamente o estado de lugar, coisa ou pessoa, na pendência de processo, para induzir a erro o juiz ou o perito.", "explicacao": "CP, art. 347. A pena dobra se o processo for penal."}, {"id": 2000003459, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Qual crime comete quem se acusa, perante a autoridade, de crime inexistente ou praticado por outro?", "verso": "Autoacusação falsa.", "explicacao": "CP, art. 341."}, {"id": 2000003460, "trilha": "policial", "materia": "leg", "assunto": "Identificação criminal", "tipo": "pergunta", "frente": "O que é o Banco Nacional de Perfis Genéticos?", "verso": "Banco que armazena perfis de DNA de condenados por certos crimes dolosos com violência grave e de vestígios de locais de crime, para fins de investigação.", "explicacao": "Lei 12.654/2012 e LEP, art. 9º-A."}, {"id": 2000003461, "trilha": "policial", "materia": "leg", "assunto": "Interceptação", "tipo": "pergunta", "frente": "Qual a pena de quem realiza interceptação telefônica sem autorização judicial?", "verso": "Reclusão de 2 a 4 anos e multa.", "explicacao": "Lei 9.296/1996, art. 10."}, {"id": 2000003462, "trilha": "policial", "materia": "leg", "assunto": "Interceptação", "tipo": "pergunta", "frente": "O que é a captação ambiental?", "verso": "A gravação de sinais eletromagnéticos, ópticos ou acústicos em ambiente, autorizada pelo juiz, para investigar crimes com pena máxima superior a 4 anos.", "explicacao": "Lei 9.296/1996, art. 8º-A, incluído pela Lei 13.964/2019."}, {"id": 2000003463, "trilha": "policial", "materia": "leg", "assunto": "Tráfico de pessoas", "tipo": "pergunta", "frente": "Quais finalidades caracterizam o tráfico de pessoas no CP?", "verso": "Remoção de órgãos, trabalho análogo ao de escravo, servidão, adoção ilegal ou exploração sexual.", "explicacao": "CP, art. 149-A, incluído pela Lei 13.344/2016."}, {"id": 2000003464, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "pergunta", "frente": "O crime de racismo prescreve?", "verso": "Não. É imprescritível e inafiançável, sujeito a pena de reclusão.", "explicacao": "CF, art. 5º, XLII."}, {"id": 2000003465, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Cabe tráfico privilegiado para quem se dedica a atividades criminosas?", "verso": "Não. O benefício exige agente primário, de bons antecedentes, que não se dedique a atividades criminosas nem integre organização criminosa.", "explicacao": "Lei 11.343/2006, art. 33, § 4º."}, {"id": 2000003466, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O que é o crime do art. 38 da Lei de Drogas?", "verso": "Prescrever ou ministrar, culposamente, drogas sem que o paciente necessite ou em dose excessiva ou em desacordo com a norma.", "explicacao": "É o único crime culposo da Lei de Drogas."}, {"id": 2000003467, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Para onde vão os bens apreendidos do tráfico, após a condenação?", "verso": "São perdidos em favor da União e revertidos ao Funad (Fundo Nacional Antidrogas).", "explicacao": "Lei 11.343/2006, art. 63, e CF, art. 243, parágrafo único."}, {"id": 2000003468, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Os crimes hediondos admitem fiança?", "verso": "Não. São insuscetíveis de anistia, graça, indulto e fiança.", "explicacao": "Lei 8.072/1990, art. 2º."}, {"id": 2000003469, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Quem tem direito a porte de arma de fogo pelo Estatuto do Desarmamento, em razão da função?", "verso": "Integrantes das Forças Armadas, dos órgãos de segurança pública do art. 144, das guardas municipais (nos termos da lei), agentes de inteligência e do sistema prisional, entre outros.", "explicacao": "Lei 10.826/2003, art. 6º."}, {"id": 2000003470, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Quem organiza e mantém a Polícia Federal?", "verso": "A União.", "explicacao": "CF, art. 144, § 1º."}, {"id": 2000003471, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Quais os objetivos fundamentais da República (art. 3º)?", "verso": "Construir sociedade livre, justa e solidária; garantir o desenvolvimento nacional; erradicar a pobreza e a marginalização e reduzir desigualdades; promover o bem de todos, sem preconceitos.", "explicacao": "CF, art. 3º. Começam com verbos."}, {"id": 2000003472, "trilha": "policial", "materia": "const", "assunto": "Direitos sociais", "tipo": "pergunta", "frente": "O que diz a Constituição sobre o trabalho noturno, perigoso ou insalubre?", "verso": "É proibido para menores de 18 anos, e qualquer trabalho é proibido para menores de 16, salvo como aprendiz, a partir de 14.", "explicacao": "CF, art. 7º, XXXIII."}, {"id": 2000003473, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quem julga o habeas corpus contra ato de delegado de polícia estadual?", "verso": "O juiz de direito de primeira instância.", "explicacao": "Regra de competência pela autoridade coatora."}, {"id": 2000003474, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quem julga os crimes comuns de governadores?", "verso": "O Superior Tribunal de Justiça.", "explicacao": "CF, art. 105, I, a."}, {"id": 2000003475, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da continuidade do serviço público?", "verso": "O serviço público não pode ser interrompido, salvo nas hipóteses legais.", "explicacao": "Fundamenta limites à greve e à exceção do contrato não cumprido."}, {"id": 2000003476, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da segurança jurídica na Lei 9.784?", "verso": "Veda a aplicação retroativa de nova interpretação da norma administrativa.", "explicacao": "Lei 9.784/1999, art. 2º, parágrafo único, XIII."}, {"id": 2000003477, "trilha": "policial", "materia": "adm", "assunto": "Agentes públicos", "tipo": "pergunta", "frente": "Quem são os agentes políticos?", "verso": "Os que ocupam os cargos estruturais da organização política, como chefes do Executivo, ministros, secretários e parlamentares.", "explicacao": "Classificação doutrinária dos agentes públicos."}, {"id": 2000003478, "trilha": "policial", "materia": "adm", "assunto": "Agentes públicos", "tipo": "pergunta", "frente": "Quem são os particulares em colaboração com o Estado?", "verso": "Pessoas que, sem perder a condição de particulares, exercem função pública, como jurados, mesários e conscritos.", "explicacao": "Espécie de agente público."}, {"id": 2000003479, "trilha": "policial", "materia": "adm", "assunto": "Bens públicos", "tipo": "pergunta", "frente": "Bens públicos podem ser objeto de usucapião?", "verso": "Não.", "explicacao": "CF, arts. 183, § 3º, e 191, parágrafo único, e Súmula 340 do STF."}, {"id": 2000003480, "trilha": "policial", "materia": "adm", "assunto": "Bens públicos", "tipo": "pares", "frente": "Qual a diferença entre bens de uso comum, de uso especial e dominicais?", "verso": "Uso comum: ruas, praças, rios. Uso especial: prédios onde funcionam serviços (delegacias, escolas). Dominicais: bens sem destinação pública específica, que podem ser alienados.", "explicacao": "Código Civil, arts. 99 a 101."}, {"id": 2000003481, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "lacuna", "frente": "\"Às polícias militares cabem a polícia ____ e a preservação da ordem pública.\"", "verso": "ostensiva", "explicacao": "CF, art. 144, § 5º."}, {"id": 2000003482, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "\"Ninguém será submetido a ____ nem a tratamento desumano ou degradante.\"", "verso": "tortura", "explicacao": "CF, art. 5º, III."}, {"id": 2000003483, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "\"Ninguém será processado nem sentenciado senão pela autoridade ____.\"", "verso": "competente", "explicacao": "CF, art. 5º, LIII (princípio do juiz natural)."}, {"id": 2000003484, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "\"É assegurado aos presos o respeito à integridade física e ____.\"", "verso": "moral", "explicacao": "CF, art. 5º, XLIX."}, {"id": 2000003485, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "lacuna", "frente": "\"Não há crime quando o agente pratica o fato em estado de necessidade, em legítima defesa, em estrito cumprimento de dever legal ou no exercício ____ de direito.\"", "verso": "regular", "explicacao": "CP, art. 23."}, {"id": 2000003486, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "lacuna", "frente": "\"A pena de reclusão deve ser cumprida em regime fechado, semiaberto ou aberto. A de ____, em regime semiaberto ou aberto, salvo necessidade de transferência a regime fechado.\"", "verso": "detenção", "explicacao": "CP, art. 33."}, {"id": 2000003487, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "lacuna", "frente": "\"O inquérito, nos crimes em que a ação pública depender de representação, não poderá sem ela ser ____.\"", "verso": "iniciado", "explicacao": "CPP, art. 5º, § 4º."}, {"id": 2000003488, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "lacuna", "frente": "\"As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de ____ contra o responsável nos casos de dolo ou culpa.\"", "verso": "regresso", "explicacao": "CF, art. 37, § 6º."}, {"id": 2000003489, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "certo_errado", "frente": "Certo ou errado? O furto de uso (pegar a coisa só para usar e devolver logo, intacta) é crime no Código Penal comum.", "verso": "Errado. O furto de uso não é tipificado no CP (é atípico), embora seja crime no Código Penal Militar.", "explicacao": "Doutrina e jurisprudência; CPM, art. 241."}, {"id": 2000003490, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "certo_errado", "frente": "Certo ou errado? O peculato culposo admite extinção da punibilidade pela reparação do dano antes da sentença irrecorrível.", "verso": "Certo.", "explicacao": "CP, art. 312, § 3º."}, {"id": 2000003491, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "certo_errado", "frente": "Certo ou errado? Nos crimes permanentes, o agente está em flagrante enquanto não cessar a permanência.", "verso": "Certo.", "explicacao": "CPP, art. 303. Ex.: tráfico na modalidade guardar, sequestro."}, {"id": 2000003492, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "certo_errado", "frente": "Certo ou errado? O depoimento de policiais pode servir de prova para a condenação.", "verso": "Certo, desde que coerente e harmônico com as demais provas.", "explicacao": "Jurisprudência do STF e do STJ."}, {"id": 2000003493, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "certo_errado", "frente": "Certo ou errado? A associação para o tráfico (art. 35) é crime hediondo.", "verso": "Errado. Não está no rol de hediondos nem é equiparada.", "explicacao": "Entendimento do STJ."}, {"id": 2000003494, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "certo_errado", "frente": "Certo ou errado? Criança que pratica ato infracional recebe medida socioeducativa.", "verso": "Errado. Criança (até 12 anos incompletos) recebe medida de proteção. Só o adolescente recebe medida socioeducativa.", "explicacao": "ECA, arts. 105 e 112."}, {"id": 2000003495, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "certo_errado", "frente": "Certo ou errado? Os crimes de abuso de autoridade admitem a forma culposa.", "verso": "Errado. Só há forma dolosa, com finalidade específica.", "explicacao": "Lei 13.869/2019, art. 1º, § 1º."}, {"id": 2000003496, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "certo_errado", "frente": "Certo ou errado? O brasileiro naturalizado pode ser Ministro de Estado da Defesa.", "verso": "Errado. O cargo é privativo de brasileiro nato.", "explicacao": "CF, art. 12, § 3º, VII."}, {"id": 2000003497, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "certo_errado", "frente": "Certo ou errado? O analfabeto pode votar, mas não pode ser eleito.", "verso": "Certo. Para ele o voto é facultativo, e ele é inelegível.", "explicacao": "CF, art. 14, § 1º, II, a, e § 4º."}, {"id": 2000003498, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "certo_errado", "frente": "Certo ou errado? O ato administrativo nulo pode gerar direito adquirido.", "verso": "Errado. Atos ilegais não geram direitos, mas a anulação respeita o prazo decadencial de 5 anos para atos favoráveis de boa-fé.", "explicacao": "Súmula 473 do STF e Lei 9.784/1999, art. 54."}, {"id": 2000003499, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "certo_errado", "frente": "Certo ou errado? Os livores cadavéricos aparecem nas partes do corpo que ficam em contato com o solo.", "verso": "Errado. Aparecem nas partes mais baixas (declives), mas não nas áreas comprimidas pelo apoio, que ficam pálidas.", "explicacao": "Hipóstases: o sangue se acumula pela gravidade."}, {"id": 2000003500, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "certo_errado", "frente": "Certo ou errado? Um site com cadeado e HTTPS é sempre confiável.", "verso": "Errado. O HTTPS só garante que a conexão é criptografada; sites falsos também podem usá-lo.", "explicacao": "Golpes de phishing usam HTTPS com frequência."}]$c$::jsonb)
  as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
